    std::vector<int> nums = {1, 1, 2};
    int result = removeDuplicates(nums);
    std::cout << "Output: " << result << ", nums: ";
    for (int num : nums) {
        std::cout << num << ", ";
    }
    std::cout << std::endl;
    return 0;
}
