int removeDuplicates(std::vector<int>& nums) {
    if (nums.empty()) return 0;
    int i = 0;
    for (int j = 1; j < nums.size(); ++j) {
        if (nums[j] != nums[i]) {
            i++;
            nums[i] = nums[j];
        }
    }
    return i + 1;
}

// Test case
int main() {
    std::vector<int> nums = {1, 1, 2};
    int result = removeDuplicates(nums);
    std::cout << "Output: " << result << ", nums: ";
    for (int num : nums) {
        std::cout << num << ", ";
    }
    std::cout << std::endl;
    return 0;
}
