	if dividend == math.MinInt32 && divisor == -1 {
		return math.MaxInt32
	}

	sign := (dividend > 0) ^ (divisor > 0)
	dvd := abs(dividend)
	dvs := abs(divisor)
	ans := 0

	for dvd >= dvs {
		temp := dvs
		multiple := 1
		for dvd >= (temp << 1) {
			temp <<= 1
			multiple <<= 1
		}
		dvd -= temp
		ans += multiple
	}

	return ans * sign
}

