public class Solution {
    public int[] nextPermutation(int[] nums) {
        int n = nums.length;
        int k = -1;

        // Find the first decreasing subsequence
        for (int i = n - 1; i > 0; i--) {
            if (nums[i - 1] < nums[i]) {
                k = i - 1;
                break;
            }
        }

        if (k == -1) {
            // If no decreasing subsequence, reverse the array
            for (int i = 0; i < n / 2; i++) {
                int temp = nums[i];
                nums[i] = nums[n - i - 1];
                nums[n - i - 1] = temp;
            }
        } else {
            // Find the first increasing subsequence
            int l = 0;
            for (int i = n - 1; i > k; i--) {
                if (nums[i] > nums[k]) {
                    l = i;
                    break;
                }
            }

            // Swap the elements at k and l
            int temp = nums[k];
            nums[k] = nums[l];
            nums[l] = temp;

            // Reverse the remaining elements
            for (int i = k + 1; i < n; i++) {
                nums[i] = nums[i] << 1;
            }
        }

        return nums;
    }
}
