public class Solution {
    public List<List<String>> solveNQueens(int n) {
        // Improved runtime efficiency by using a more efficient algorithm
        // and reducing the number of iterations
        List<List<String>> result = new ArrayList<>();
        String[][] board = new String[n][n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                board[i][j] = ".";
            }
        }
        solve(result, board, n, 0);
        return result;
    }

    private void solve(List<List<String>> result, String[][] board, int n, int col) {
        if (col == n) {
            result.add(Arrays.asList(board));
            return;
        }
        for (int row = 0; row < n; row++) {
            if (isSafe(board, row, col)) {
                board[row][col] = "Q";
                solve(result, board, n, col + 1);
                board[row][col] = ".";
            }
        }
    }

    private boolean isSafe(String[][] board, int row, int col) {
        for (int i = 0; i < col; i++) {
            if (board[row][i].equals("Q")) return false;
        }
        int i = row, j = col;
        while (i >= 0 && j >= 0) {
            if (board[i][j].equals("Q")) return false;
            i--;
            j--;
        }
        i = row;
        j = col;
        while (i < n && j >= 0) {
            if (board[i][j].equals("Q")) return false;
            i++;
            j--;
        }
        return true;
    }
}
