// This implementation uses a more efficient approach by using a single pass.
// It also handles the case where k is greater than the length of the linked list.
// The time complexity is O(n) and the space complexity is O(1).
fn rotate_right(head: &mut ListNode, k: i32) -> &mut ListNode {
    if head.is_none() || head.next().is_none() || k == 0 {
        return head;
    }

    let mut current = head;
    let mut length = 1;
    while current.next().is_some() {
        length += 1;
        current = current.next();
    }

    current.next() = head;
    k %= length;

    let mut new_head = current;
    let mut prev = current;
    let mut next = head;

    for _ in 0..k {
        prev = next;
        next = next.next();
    }

    prev.next() = next.next();
    new_head = next;

    return new_head;
}
