    parts = path.split("/")
    stack = []

    for part in parts:
        if not part or part == ".":
            continue
        if part == "..":
            if stack:
                stack.pop()
        else:
            stack.append(part)

    canonical_path = ""
    for piece in stack:
        canonical_path += "/" + piece
    return "/" if not stack else canonical_path
