import java.util.HashMap;
import java.util.Map;

public class Solution {
    public String minWindow(String s, String t) {
        // Use a HashMap to count the occurrences of characters in the target string
        Map<Character, Integer> need = new HashMap<>();
        for (char c : t.toCharArray()) {
            need.put(c, need.getOrDefault(c, 0) + 1);
        }

        // Use a HashMap to count the occurrences of characters in the sliding window
        Map<Character, Integer> window = new HashMap<>();
        int left = 0, right = 0, valid = 0, start = 0, length = Integer.MAX_VALUE;

        while (right < s.length()) {
            char c = s.charAt(right);
            right++;

            // If the character is in the target string, increment its count in the window
            if (need.containsKey(c)) {
                window.put(c, window.getOrDefault(c, 0) + 1);
                if (window.get(c).equals(need.get(c))) {
                    valid++;
                }
            }

            // Move the left pointer until the window is valid
            while (valid == need.size()) {
                if (right - left < length) {
                    start = left;
                    length = right - left;
                }

                char d = s.charAt(left);
                left++;

                // If the character is in the target string, decrement its count in the window
                if (need.containsKey(d)) {
                    if (window.get(d).equals(need.get(d))) {
                        valid--;
                    }
                    window.put(d, window.get(d) - 1);
                }
            }
        }

        return length == Integer.MAX_VALUE ? "" : s.substring(start, start + length);
    }
}
