#include <string>
#include <map>
#include <iostream>

std::string minWindow(const std::string& s, const std::string& t) {
    std::map<char, int> need;
    for (char c : t) {
        need[c]++;
    }

    int left = 0, right = 0, valid = 0, start = 0, length = INT_MAX;

    while (right < s.size()) {
        char c = s[right];
        right++;

        if (need.find(c) != need.end()) {
            need[c]--;
            if (need[c] >= 0) {
                valid++;
            }
        }

        while (valid == need.size()) {
            if (right - left < length) {
                start = left;
