public List<String> findRanges(int[] nums) {
    List<String> result = new ArrayList<>();
    int n = nums.length;
    if (n == 0) return result;

    int start = nums[0];
    for (int i = 1; i < n; i++) {
        if (nums[i] > nums[i-1] + 1) {
