std::string alienOrder(std::vector<std::string> words) {
    std::unordered_map<char, int> in_degree;
    std::unordered_map<char, std::vector<char>> graph;

    for (const auto& word : words) {
        for (char c : word) {
            in_degree[c] = 0;
        }
    }

    for (int i = 0; i < words.size() - 1; ++i) {
        const auto& word1 = words[i];
        const auto& word2 = words[i + 1];

        for (int j = 0; j < std::min(word1.size(), word2.size()); ++j) {
            if (word1[j] != word2[j]) {
                if (graph.find(word2[j]) == graph.end()) {
                    graph[word2[j]].push_back(word1[j]);
                    in_degree[word1[j]]++;
                } else {
                    return "";
                }
                break;
            }
        }

        if (word1.size() > word2.size()) {
            return "";
        }
    }

    std::queue<char> q;
    for (char c : in_degree) {
        if (in_degree[c] == 0) {
            q.push(c);
        }
    }

    std::string result;
    while (!q.empty()) {
        char c = q.front();
        q.pop();
        result.push_back(c);

        for (char neigh : graph[c]) {
            in_degree[neigh]--;
            if (in_degree[neigh] == 0) {
                q.push(neigh);
            }
        }
    }

    return result.empty() ? "" : result;
}

