public:
    vector<string> removeInvalidParentheses(string s) {
        set<string> visited;
        queue<string> q;
        vector<string> result;
        bool found = false;

        visited.insert(s);
        q.push(s);

        while (!q.empty()) {
            string cur = q.front();
            q.pop();

            if (isValid(cur)) {
                found = true;
                result.push_back(cur);
            }

            if (found) continue;

            for (int i = 0; i < cur.length(); ++i) {
                if (cur[i] == '(' || cur[i] == ')') {
                    string next = cur.substr(0, i) + cur.substr(i+1);
                    if (visited.find(next) == visited.end()) {
                        visited.insert(next);
                        q.push(next);
                    }
                }
            }
        }
        return result;
