import java.util.*;

public class Solution {
    public int[] numIslands2(int m, int n, int[][] positions) {
        // Initialize a 2D array to represent the grid
        int[][] grid = new int[m][n];

        // Use a set to keep track of visited cells
        Set<Integer> visited = new HashSet<>();

        // Use a queue to traverse the grid
        Queue<int[]> queue = new LinkedList<>();

        // Initialize the root of each cell
        int[][] roots = new int[m][n];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                roots[i][j] = i * n + j;
            }
        }

        // Count the number of islands
        int islandCount = 0;

        // Iterate over the positions
        for (int[] position : positions) {
            int i = position[0];
            int j = position[1];

            // Check if the cell is already visited
            if (visited.contains(i * n + j)) {
                continue;
            }

            // Mark the cell as visited
            visited.add(i * n + j);

            // Add the cell to the queue
            queue.add(new int[]{i, j});

            // Update the root of the cell
            int root = roots[i][j];
            while (!queue.isEmpty()) {
                int[] current = queue.poll();
                int x = current[0];
                int y = current[1];

                // Check if the cell is not the root
                if (roots[x][y] != root) {
                    // Update the root of the cell
                    roots[x][y] = root;
                    islandCount--;
