                // Add the neighbors to the queue
                if (x > 0) {
                    queue.add(new int[]{x - 1, y});
                }
                if (x < m - 1) {
                    queue.add(new int[]{x + 1, y});
                }
                if (y > 0) {
                    queue.add(new int[]{x, y - 1});
                }
                if (y < n - 1) {
                    queue.add(new int[]{x, y + 1});
                }
            }

            // Add the island to the result
            islandCount++;
            result.add(islandCount);
        }

        return result;
    }
