        int maxLen = 0;
        for (int k = 0; k < 4; k++) {
            int ni = i + (k == 0 ? 0 : 1);
            int nj = j + (k == 1 ? 0 : 1);
            if (ni >= 0 && ni < m && nj >= 0 && nj < n && matrix[ni][nj] > matrix[i][j]) {
                maxLen = Math.max(maxLen, dfs(matrix, memo, ni, nj));
            }
