func validUtf8(data []int) bool {
	count := 0
	for _, byteValue := range data {
		if count == 0 {
			if ((byteValue >> 5) & 0b110) == 0b110 {
				count = 1
			} else if ((byteValue >> 4) & 0b1110) == 0b1110 {
				count = 2
			} else if ((byteValue >> 3) & 0b11110) == 0b11110 {
				count = 3
			} else if ((byteValue >> 7) & 1) == 1 {
				return false
			}
		} else {
			if ((byteValue >> 6) & 0b10) != 0b10 {
				return false
			}
			count--
		}
	}
	return count == 0
}

