    int totalChars = 0;
    for (String word : sentence) {
        totalChars += word.length() + 1;
    }

    int result = 0;
    int index = 0;
    for (int r = 0; r < rows; ++r) {
        int remainingCols = cols;
        while (true) {
            int wordLen = sentence[index].length();
            if (remainingCols >= wordLen) {
                remainingCols -= wordLen + 1;
                index = (index + 1) % sentence.length;
                if (index == 0) result++;
            } else {
                break;
            }
        }
    }

    return result;
}
