public int findMaximumXOR(int[] nums) {
    int max_xor = 0;
    int mask = 0;

    for (int i = 31; i >= 0; i--) {
        mask |= (1 << i);
        Set<Integer> prefixes = new HashSet<>();
        for (int num : nums) {
            prefixes.add(num & mask);
        }

        int possible_max = max_xor | (1 << i);

        for (int prefix : prefixes) {
            if (prefix ^ possible_max == prefix) {
                max_xor = possible_max;
                break;
            }
        }
    }

    return max_xor;
}
