import java.util.*;
import java.util.stream.Collectors;

public class Solution {
    public String findDigitsInAscendingOrder(String s) {
        Map<Character, Integer> count = new HashMap<>();
        for (char c : s.toCharArray()) {
            count.put(c, count.getOrDefault(c, 0) + 1);
        }

        count.put('o', count.get('o') - (count.get('w') + count.get('u') + count.get('x')));
        count.put('h', count.get('h') - count.get('g'));
        count.put('f', count.get('f') - count.get('u'));
        count.put('s', count.get('s') - count.get('x'));
        count.put('i', count.get('i') - (count.get('f') + count.get('s') + count.get('g')));

        StringBuilder result = new StringBuilder();
        for (int i = 0; i < 10; i++) {
            for (int j = 0; j < count.getOrDefault(i, 0); j++) {
                result.append(i);
            }
        }
        return result.toString();
    }
}
