import java.util.*;

public class Solution {
    public int minMutation(String start, String end, String[] bank) {
        // Use a queue to store the current gene and its depth
        Queue<String> q = new LinkedList<>();
        q.offer(start);
        Set<String> visited = new HashSet<>();
        visited.add(start);
        int depth = 0;

        while (!q.isEmpty()) {
            int levelSize = q.size();
            for (int i = 0; i < levelSize; i++) {
                String current = q.poll();
                if (current.equals(end)) {
                    return depth;
                }

                // Iterate over the bank and find a gene that differs by one mutation
                for (String gene : bank) {
                    if (!visited.contains(gene)) {
                        int diff = 0;
                        for (int j = 0; j < 8; j++) {
                            if (current.charAt(j) != gene.charAt(j)) {
                                diff++;
                            }
                        }
                        if (diff == 1) {
                            q.offer(gene);
                            visited.add(gene);
                        }
                    }
                }
            }
            depth++;
        }
        return -1;
    }
}
