public int fourSumCount(int[] nums1, int[] nums2, int[] nums3, int[] nums4) {
    Map<Integer, Integer> hashMap = new HashMap<>();
    int count = 0;

    for (int i : nums1) {
        for (int j : nums2) {
            hashMap.put(i + j, hashMap.getOrDefault(i + j, 0) + 1);
        }
    }

    for (int k : nums3) {
        for (int l : nums4) {
            count += hashMap.getOrDefault(-(k + l), 0);
        }
    }

    return count;
}
