    int[] cnt = new int[26];
    int length = 0;

    for (int i = 0; i < p.length(); i++) {
        if (i > 0 && (p.charAt(i) == (char) (p.charAt(i - 1) + 1) || (p.charAt(i - 1) - p.charAt(i)) == 25)) {
            length++;
