import java.util.HashMap;
import java.util.Map;

public class Solution {
    public int findMinStep(String board, String hand) {
        // Improved runtime efficiency by using a more efficient data structure
        Map<String, Integer> memo = new HashMap<>();

        // Base case: If the board is empty, return 0
        if (board.isEmpty()) {
            return 0;
        }

        // Recursive function to find the minimum number of steps
        int findMinStepHelper(String board, Map<String, Integer> memo, Map<String, Integer> handCount) {
            if (!board.isEmpty()) {
                // Check if the board has already been memoized
                if (memo.containsKey(board)) {
                    return memo.get(board);
                }

                int result = Integer.MAX_VALUE;
                int i = 0;
                while (i < board.length()) {
                    int j = i;
                    while (j < board.length() && board.charAt(i) == board.charAt(j)) {
                        j++;
                    }

                    char color = board.charAt(i);
                    int required = 3 - (j - i);
                    if (handCount.containsKey(color) && handCount.get(color) >= required) {
                        handCount.put(color, handCount.get(color) - required);
                        String nextBoard = board.substring(0, i) + board.substring(j);
                        int tmp = findMinStepHelper(nextBoard, memo, handCount);
                        if (tmp != -1) {
                            result = Math.min(result, tmp + required);
                        }
                        handCount.put(color, handCount.get(color) + required);
                    }
                    i = j;
                }

                memo.put(board, result == Integer.MAX_VALUE ? -1 : result);
                return memo.get(board);
            }
            return -1;
        }

        // Count the number of each color in the hand
        Map<String, Integer> handCount = new HashMap<>();
        for (char color : hand.toCharArray()) {
            handCount.put(color + "", handCount.getOrDefault(color + "", 0) + 1);
        }

        return findMinStepHelper(board, memo, handCount);
    }
}
