            const color = board[i];
            const required = 3 - (j - i);
            if (hand.get(color) >= required) {
                hand.set(color, hand.get(color) - required);
                const nextBoard = board.slice(0, i) + board.slice(j);
                const tmp = findMinStepHelper(nextBoard, memo, hand);
                if (tmp !== undefined) {
                    result = Math.min(result, tmp + required);
                }
                hand.set(color, hand.get(color) + required);
            }
            i = j;
        }

        memo.set(board, result === Number.MAX_SAFE_INTEGER ? -1 : result);
