fn merge_sort(nums: &mut Vec<i32>, left: i32, right: i32, temp: &mut Vec<i32>) -> i32 {
    if left >= right {
        return 0;
    }
    let mid: i32 = (left + right) / 2;
    let count = merge_sort(nums, left, mid, temp) + merge_sort(nums, mid + 1, right, temp);
