fn merge(nums: &mut Vec<i32>, left: i32, mid: i32, right: i32, temp: &mut Vec<i32>) -> i32 {
    let count = 0;
    temp.clone_from_slice(&nums[left..=mid + 1]);
    let mut i = left;
    let mut j = mid + 1;
    let mut k = left;
    while i <= mid && j <= right {
        if temp[i] <= temp[j] {
            nums[k] = temp[i];
            i += 1;
