```c#
using System;
using System.Collections.Generic;

namespace LeetCode {
    public class Solution {
        public int ReversePairs(int[] nums) {
            return MergeSort(nums, 0, nums.Length - 1, new int[nums.Length]);
        }

        private int MergeSort(int[] nums, int left, int right, int[] temp) {
            if (left >= right) {
                return 0;
            }
            int mid = left + (right - left) / 2;
            int count = MergeSort(nums, left, mid, temp) + MergeSort(nums, mid + 1, right, temp);
            count += Merge(nums, left, mid, right, temp);

            return count;
        }

        private int Merge(int[] nums, int left, int mid, int right, int[] temp) {
            int count = 0;
            Array.Copy(nums, left, temp, left, right - left + 1);
            int i = left;
            int j = mid + 1;
            while (i <= mid && j <= right) {
                if (temp[i] <= temp[j]) {
                    nums[left++] = temp[i++];
                } else {
                    nums[left++] = temp[j++];
                    count += j - (mid + 1);
                }
            }
            while (i <= mid) {
                nums[left++] = temp[i++];
            }
            while (j <= right) {
                nums[left++] = temp[j++];
            }

            return count;
        }
    }
}

