int findTargetSumWays(std::vector<int>& nums, int target) {
    int total_sum = 0;
    for (int num : nums) {
        total_sum += num;
    }
    if (total_sum < target || (total_sum + target) % 2 != 0) {
        return 0;
    }
    int target_sum = (total_sum + target) / 2;
    std::vector<int> dp(target_sum + 1, 0);
    dp[0] = 1;
    for (int num : nums) {
        for (int j = target_sum; j >= num; j--) {
            dp[j] += dp[j - num];
        }
    }
    return dp[target_sum];
}

