    int target_sum = (total_sum + target) / 2;
    std::vector<int> dp(target_sum + 1, 0);
    dp[0] = 1;
    for (int num : nums) {
        for (int j = target_sum; j >= num; j--) {
            dp[j] += dp[j - num];
        }
    }
    return dp[target_sum];
}

int main() {
    std::vector<int> nums = {1, 1, 1, 1, 1};
    int target = 3;
    std::cout << findTargetSumWays(nums, target) << std::endl;
    return 0;
}
