import java.util.PriorityQueue;

public class Solution {
    public int findMaximizedCapital(int k, int w, int[] profits, int[] capital) {
        // Create a list of projects sorted by their capital requirements
        List<Project> projectPool = new ArrayList<>();
        for (int i = 0; i < profits.length; i++) {
            projectPool.add(new Project(capital[i], profits[i]));
        }
        projectPool.sort((p1, p2) -> Integer.compare(p2.getCapital(), p1.getCapital()));

        // Create a priority queue to store the maximum profit from each project
        PriorityQueue<Integer> profitPool = new PriorityQueue<>(Collections.reverseOrder());

        // Simulate the investment process
        for (int i = 0; i < k; i++) {
            // If there are projects with a capital requirement less than or equal to the current investment
            while (!projectPool.isEmpty() && projectPool.get(0).getCapital() <= w) {
                profitPool.offer(-projectPool.remove().getProfit());
            }

            // If the priority queue is not empty, remove the maximum profit and update the investment
            if (!profitPool.isEmpty()) {
                w -= profitPool.poll();
            }
        }

        return w;
    }

    private static class Project {
        int capital;
        int profit;

        Project(int capital, int profit) {
            this.capital = capital;
            this.profit = profit;
        }

        int getCapital() {
            return capital;
        }

        int getProfit() {
            return profit;
        }
    }
}
