#include <vector>
#include <algorithm>

std::vector<std::string> find_relative_ranks(const std::vector<int>& score) {
    std::vector<int> rank_sort(score.size());
    std::iota(rank_sort.begin(), rank_sort.end(), 0);
    std::sort(rank_sort.begin(), rank_sort.end(), 
              [&score](int i, int j) { return score[i] > score[j]; });

    std::vector<std::string> result(score.size());
    for (int i = 0; i < score.size(); ++i) {
        result[rank_sort[i]] = std::to_string(i + 1);
    }
    return result;
}
