public int findMinDifference(String[] timePoints) {
    // Sort the time points in ascending order
    Arrays.sort(timePoints, (a, b) -> {
        int h1 = Integer.parseInt(a.split(":")[0]);
        int m1 = Integer.parseInt(a.split(":")[1]);
        int h2 = Integer.parseInt(b.split(":")[0]);
        int m2 = Integer.parseInt(b.split(":")[1]);
        return h1 * 60 + m1 - h2 * 60 - m2;
    });

    int minDifference = Integer.MAX_VALUE;

    for (int i = 0; i < timePoints.length; i++) {
        String time1 = timePoints[i];
        String time2 = timePoints[(i + 1) % timePoints.length];

        int h1 = Integer.parseInt(time1.split(":")[0]);
        int m1 = Integer.parseInt(time1.split(":")[1]);
        int h2 = Integer.parseInt(time2.split(":")[0]);
        int m2 = Integer.parseInt(time2.split(":")[1]);

        int difference = Math.abs((h1 * 60 + m1) - (h2 * 60 + m2));
        minDifference = Math.min(minDifference, 1440 - difference, difference);
    }

    return minDifference;
}
