public class Solution {
    public int removeBoxes(int[] boxes) {
        // Initialize a 2D array to store the results of the recursive function calls
        int[][][] dp = new int[boxes.length][boxes.length][100];

        // Base case: If the left and right indices are the same, return 0
        if (left == right) {
            return 0;
        }

        // Initialize the current index and the number of boxes to be moved
        int current = left;
        int k = 0;

        // Move boxes to the right until the current index is greater than the right index
        while (current <= right && boxes[current] == boxes[current - 1]) {
            current++;
            k++;
        }

        // Recursively call the function to calculate the result
        int result = (k * k + 1) * removeBoxes(boxes, left, current - 1, right);

        // Move the boxes to the left
        for (int i = left; i < current; i++) {
            if (boxes[i] == boxes[current]) {
                // Recursively call the function to calculate the result
                result = Math.max(result, removeBoxes(boxes, left, i, current - 1) + removeBoxes(boxes, i + 1, right, current - 1));
            }
        }

        return result;
    }

    // Function to remove boxes from the array
    private int[] removeBoxes(int[] boxes, int left, int current, int right) {
        // Initialize the result array
        int[] result = new int[boxes.length];

        // Copy the boxes from the left index to the current index
        for (int i = left; i < current; i++) {
            result[i] = boxes[i];
        }

        // Copy the boxes from the current index to the right index
        for (int i = current; i <= right; i++) {
            result[i] = boxes[i];
        }

        return result;
    }
}
