int leastBricks(std::vector<std::vector<int>> wall) {
    std::unordered_map<int, int> edgeCount;
    int maxCount = 0;

    for (const auto& row : wall) {
        int edgePosition = 0;
        for (int i = 0; i < row.size() - 1; ++i) {
            edgePosition += row[i];
            ++edgeCount[edgePosition];
            maxCount = std::max(maxCount, edgeCount[edgePosition]);
        }
    }

    return wall.size() - maxCount;
}

int main() {
    std::vector<std::vector<int>> wall = {{1, 2, 2, 1}, {3, 1, 2}, {1, 3, 2}, {2, 4}, {3, 1, 2}, {1, 3, 1, 1}};
    std::cout << leastBricks(wall) << std::endl;
    return 0;
}
