        String[] strs = {"abc ", "xyz "};
        System.out.println(splitLoopedString(strs));
    }

    private static String splitLoopedString(String[] strs) {
        String ans = "";
        String cur = "";

        for (String s : strs) {
            cur = Math.max(cur, s + s.reverse());
        }

        for (String s : strs) {
            for (int i = 0; i < s.length(); i++) {
                String t = s.substring(i) + cur.substring(s.length()) + cur.substring(0, s.length()) + s.substring(0, i);
                ans = Math.max(ans, t);
            }
            cur = cur.substring(s.length()) + cur.substring(0, s.length());
        }

        return ans;
    }
}
