import java.util.*;

public class Solution {
    public int findPaths(int m, int n, int maxMove, int startRow, int startColumn) {
        // Initialize the 2D array to store the number of paths
        int[][][] dp = new int[maxMove + 1][m][n];
        // Define the possible moves
        int[][] moves = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

        // Initialize the first row and column
        for (int k = 1; k <= maxMove; k++) {
            for (int i = 0; i < m; i++) {
                for (int j = 0; j < n; j++) {
                    // If the cell is out of bounds, set the value to 1
                    if (i < 0 || i >= m || j < 0 || j >= n) {
                        dp[k][i][j] = 1;
                    } else {
                        // If the cell is not out of bounds, calculate the number of paths
                        dp[k][i][j] = (dp[k][i][j] + dp[k - 1][i][j]) % 1000000007;
                    }
                }
            }
        }

        // Return the value of the cell at the starting position
        return dp[maxMove][startRow][startColumn];
    }
}
