def cross_product(p, q, r):
    return (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])

def compare(p, q):
    return p[0] < q[0] or (p[0] == q[0] and p[1] < q[1])

def fence(trees):
    trees = np.array(trees)
    trees = trees[np.argsort(trees[:, 0])]
    hull = [trees[0]]
    for i in range(1, len(trees)):
        while len(hull) >= 2 and cross_product(hull[-2], hull[-1], trees[i]) > 0:
            hull.pop()
        hull.append(trees[i])
    for i in range(len(trees) - 1, 0, -1):
        p = trees[i]
        while len(hull) >= 2 and cross_product(hull[-2], hull[-1], p) > 0:
            hull.pop()
        hull.append(p)
    return hull.tolist()

