int findLHS(int* nums, int size) {
    std::unordered_map<int, int> count;
    for (int i = 0; i < size; i++) {
        count[nums[i]]++;
    }

    int longest_sequence = 0;
    for (auto& pair : count) {
        if (count.find(pair.first + 1) != count.end()) {
            longest_sequence = std::max(longest_sequence, pair.second + count[pair.first + 1]);
