#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>

std::vector<std::vector<std::string>> findDuplicate(const std::vector<std::string>& paths) {
    std::unordered_map<std::string, std::vector<std::string>> content_map;
    for (const auto& path : paths) {
        std::string directory, content;
        std::string file_path;
        std::istringstream iss(path);
        std::string token;
        while (iss >> token) {
            if (token == "(") {
                content = token;
                break;
            }
            directory += token + " ";
        }
        std::string file = directory;
        while (iss >> token) {
            if (token == ")") {
                content_map[content].push_back(file);
                break;
            }
            file += " " + token;
        }
    }

    std::vector<std::vector<std::string>> result;
    for (const auto& pair : content_map) {
        if (pair.second.size() > 1) {
            result.push_back(pair.second);
        }
    }
    return result;
}

int main() {
    std::vector<std::string> paths = {"root/a 1.txt(abcd) 2.txt(efgh)", "root/c 3.txt(abcd)", "root/c/d 4.txt(efgh)", "root 4.txt(efgh)"};
