#include <iostream>
#include <limits>

int smallestFactorization(int num) {
    if (num == 1) {
        return 1;
    }
    int result = 0;
    int factor = 1;
    for (int i = 9; i > 1; i--) {
        while (num % i == 0) {
            num /= i;
            result += i * factor;
            factor *= 10;
            if (result > std::numeric_limits<int>::max()) {
                return 0;
            }
        }
    }
    return result ? result : 0;
}

