CREATE FUNCTION smallestFactorization(num INT) RETURNS INT
BEGIN
    IF num = 1 THEN
        RETURN 1;
    END IF;
    DECLARE result INT DEFAULT 0;
    DECLARE factor INT DEFAULT 1;
    DECLARE i INT DEFAULT 9;
    WHILE i > 1 DO
        WHILE num % i = 0 AND i <= 9 DO
            num /= i;
            result += i * factor;
            factor *= 10;
            IF result > 2147483647 THEN
                RETURN 0;
            END IF;
        END WHILE;
        i -= 1;
    END WHILE;
    RETURN result;
END
