#include <vector>
#include <algorithm>

int shoppingOffers(const std::vector<int>& price, const std::vector<std::vector<int>>& special, const std::vector<int>& needs) {
    // Helper function to calculate the cost of a given offer
    int helper(int index) {
        if (index == special.size()) {
            return sum(needs[i] * price[i] for i in range(needs.size()));
        }

        int no_offer = helper(index + 1);
        bool can_apply_offer = true;
        for (int i = 0; i < needs.size(); ++i) {
            needs[i] -= special[index][i];
            if (needs[i] < 0) {
                can_apply_offer = false;
            }
        }

        int with_offer = std::numeric_limits<int>::max();
        if (can_apply_offer) {
            int offer_cost = special[index][-1] + helper(index);
            with_offer = std::min(no_offer, offer_cost);
        }

        for (int i = 0; i < needs.size(); ++i) {
            needs[i] += special[index][i];
        }

        return with_offer if can_apply_offer else no_offer;
    }

    return helper(0);
}
