import java.util.*;

public class Solution {
    public String predictPartyVictory(String senate) {
        // Use a deque to store the indices of the radiant and dire parties
        Deque<Integer> radiant = new LinkedList<>();
        Deque<Integer> dire = new LinkedList<>();
        int n = senate.length();

        // Initialize the radiant and dire parties
        for (int i = 0; i < senate.length(); i++) {
            if (senate.charAt(i) == 'R') {
                radiant.add(i);
            } else {
                dire.add(i);
            }
        }

        // Simulate the election process
        while (!radiant.isEmpty() && !dire.isEmpty()) {
            // Get the indices of the radiant and dire parties
            int r = radiant.peek();
            int d = dire.peek();

            // Move the radiant party to the end of the senate
            if (r < d) {
                radiant.add(r + n);
            } else {
                dire.add(d + n);
            }
        }

        // Check if the radiant party still exists
        return "Radiant" if radiant.isEmpty() else "Dire";
    }
}
