fn findNumberOfLIS(nums: &Vec<i32>) -> i32 {
    let n = nums.len();
    let mut maxLength = 0;
    let mut ans = 0;
    let mut length = vec![0; n];
    let mut count = vec![0; n];

    for i in 0..n {
        length[i] = count[i] = 1;
        for j in 0..i {
            if nums[i] > nums[j] {
                if length[i] === length[j] + 1 {
                    count[i] += count[j];
                } else if length[i] < length[j] + 1 {
                    length[i] = length[j] + 1;
                    count[i] = count[j];
                }
            }
        }
        if maxLength === length[i] {
            ans += count[i];
        } else if maxLength < length[i] {
            maxLength = length[i];
            ans = count[i];
        }
    }

    return ans;
}

