public class Solution {
    public double knightProbability(int n, int k, int row, int column) {
        // Initialize a 2D array to store the results of each possible move
        double[][][] memo = new double[n][n][k + 1];

        // Base case: If the knight is at the starting position and k moves are left, the probability is 1
        if (row == 0 && column == 0 && k == 0) {
            return 1.0;
        }

        // Base case: If the knight is out of bounds, the probability is 0
        if (row < 0 || row >= n || column < 0 || column >= n) {
            return 0.0;
        }

        // If the result has already been calculated, return it
        if (memo[row][column][k] >= 0) {
            return memo[row][column][k];
        }

        // Calculate the probability of each possible move
        double result = 0.0;
        int[][] moves = {{-2, -1}, {-2, 1}, {-1, -2}, {-1, 2}, {1, -2}, {1, 2}, {2, -1}, {2, 1}};
        for (int[] move : moves) {
            result += knightProbability(n, k - 1, row + move[0], column + move[1]) / 8.0;
        }

        // Store the result
        memo[row][column][k] = result;

        return result;
    }
}
