#include <vector>
#include <algorithm>

int max_points(const std::vector<int>& nums) {
    std::vector<int> dp(100001, 0);
    int max_points = 0;
    for (int num : nums) {
        dp[num] += 1;
    }
    for (int i = 2; i < dp.size(); ++i) {
        dp[i] = std::max(dp[i - 1], dp[i - 2] + i * dp[i]);
        max_points = std::max(max_points, dp[i]);
    }
    return max_points;
}
