import heapq
from typing import List

def networkDelayTime(times: List[List[int]], n: int, k: int) -> int:
    graph = [[] for _ in range(n + 1)]
    for u, v, w in times:
        graph[u].append((v, w))

    dist = [float('inf')] * (n + 1)
    dist[k] = 0
    pq = [(0, k)]

    while pq:
        _, u = heapq.heappop(pq)
        if dist[u] < float('inf'):
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(pq, (dist[v], v))

    max_time = 0
    for i in range(1, n + 1):
        if dist[i] == float('inf'):
            return -1
        max_time = max(max_time, dist[i])

    return max_time
