#include <vector>
#include <algorithm>

int orderOfLargestPlusSign(int n, std::vector<std::vector<int>>& mines) {
    std::vector<std::vector<int>> grid(n, std::vector<int>(n, 1));
    for (const auto& mine : mines) {
        grid[mine[0]][mine[1]] = 0;
    }

    std::vector<std::vector<int>> left(n, std::vector<int>(n, 0));
    std::vector<std::vector<int>> up(n, std::vector<int>(n, 0));
    std::vector<std::vector<int>> right(n, std::vector<int>(n, 0));
    std::vector<std::vector<int>> down(n, std::vector<int>(n, 0));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j]) {
                left[i][j] = 1 + (left[i][j - 1] ? left[i][j - 1] : 0);
                up[i][j] = 1 + (up[i - 1][j] ? up[i - 1][j] : 0);
            }
        }
    }

    int ans = 0;
    for (int i = n - 1; i >= 0; --i) {
        for (int j = n - 1; j >= 0; --j) {
            if (grid[i][j]) {
                right[i][j] = 1 + (right[i][j + 1] ? right[i][j + 1] : 0);
                down[i][j] = 1 + (down[i + 1][j] ? down[i + 1][j] : 0);
                ans = std::max(ans, std::min(left[i][j], right[i][j], up[i][j], down[i][j]));
            }
        }
    }

    return ans;
}
