int numRabbits(const std::vector<int>& answers) {
    std::unordered_map<int, int> count;
    int rabbits = 0;
    for (int ans : answers) {
        count[ans]++;
    }
    for (auto& pair : count) {
        rabbits += (pair.first + pair.second) / (pair.first + 1) * (pair.first + 1);
    }
    return rabbits;
}

