public boolean isBipartite(int[][] graph) {
    int n = graph.length;
    boolean[] colors = new boolean[n];
    for (int i = 0; i < n; i++) {
        if (!colors[i] && !dfs(graph, i, 1)) {
            return false;
        }
    }
    return true;
}

private boolean dfs(int[][] graph, int node, int color) {
    if (colors[node]) {
        return colors[node] == color;
    }
    colors[node] = color;
    for (int neighbor : graph[node]) {
        if (!dfs(graph, neighbor, 3 - color)) {
            return false;
        }
    }
    return true;
}
```
```python
def isBipartite(graph: List[List[int]]) -> bool:
    def dfs(node: int, color: int) -> bool:
        if colors[node]:
            return colors[node] == color

        colors[node] = color
        for neighbor in graph[node]:
            if not dfs(neighbor, 3 - color):
                return False

        return True

    n = len(graph)
    colors = [0] * n

    for i in range(n):
        if not colors[i] and not dfs(i, 1):
            return False

    return True
