int maxProfitAssignment(std::vector<int>& difficulty, std::vector<int>& profit, std::vector<int>& worker) {
    std::vector<std::pair<int, int>> jobs = {{difficulty[0], profit[0]}};
    for (int i = 1; i < difficulty.size(); ++i) {
        jobs.push_back({difficulty[i], profit[i]});
    }
    std::sort(jobs.begin(), jobs.end());

    std::vector<int> sortedWorker = worker;
    std::sort(sortedWorker.begin(), sortedWorker.end());

    int max_profit = 0;
    int total_profit = 0;
    int job_idx = 0;

    for (int w : sortedWorker) {
        while (job_idx < jobs.size() && w >= jobs[job_idx].first) {
            max_profit = std::max(max_profit, jobs[job_idx].second);
            job_idx++;
        }
        total_profit += max_profit;
    }

    return total_profit;
}
