class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode(int x) { val = x; }
}

class Solution {
    public TreeNode subtreeWithAllDeepest(TreeNode root) {
        // Find the deepest subtree
        TreeNode deepest = findDeepest(root);
        return deepest;
    }

    private TreeNode findDeepest(TreeNode node) {
        if (node == null) {
            return null;
        }
        TreeNode left = findDeepest(node.left);
        TreeNode right = findDeepest(node.right);
        if (left == null || right == null) {
            return left == null ? right : left;
        }
        // If both subtrees are equally deep, return the node
        return node;
    }
}
