public int lenLongestFibSubseq(int[] arr) {
    int n = arr.length;
    Map<Integer, Integer> index = new HashMap<>();
    for (int i = 0; i < n; ++i)
        index.put(arr[i], i);

    Map<Integer, Integer> longest = new HashMap<>();
    int ans = 0;

    for (int k = 0; k < n; ++k)
        for (int j = 0; j < k; ++j) {
