#include <set>
#include <algorithm>

int numSpecialEquivalentGroups(std::vector<std::string> words) {
    std::set<std::string> groups;

    for (const auto& word : words) {
        std::string evenWord, oddWord;

        for (char c : word) {
            if (c % 2 == 0) evenWord += c;
            else oddWord += c;
        }

        std::sort(evenWord.begin(), evenWord.end());
        std::sort(oddWord.begin(), oddWord.end());

        groups.insert(evenWord + oddWord);
    }

    return groups.size();
}
