#include <iostream>
#include <vector>
#include <algorithm>

int minDifference(const std::vector<int>& nums, int k) {
    if (nums.empty() || nums.size() <= 1) return 0;
    nums.sort();
    int min_diff = nums.back() - nums.front();
    for (int i = 1; i < nums.size(); ++i) {
        int high = std::max(nums[i - 1] + k, nums.back() - k);
        int low = std::min(nums[i] - k, nums.front() + k);
        min_diff = std::min(min_diff, high - low);
    }
    return min_diff;
}

int main() {
    std::vector<int> nums = {1, 2, 3, 4, 5};
    std::cout << minDifference(nums, 2) << std::endl;
    return 0;
}
