#include <iostream>
#include <vector>
#include <algorithm>

int threeSumMulti(std::vector<int>& arr, int target) {
    int MOD = 1000000007;
    int ans = 0;

    std::sort(arr.begin(), arr.end());

    for (int i = 0; i < arr.size() - 2; ++i) {
        int j = i + 1;
        int k = arr.size() - 1;

        while (j < k) {
            int sum = arr[i] + arr[j] + arr[k];
            if (sum > target) {
                --k;
            } else if (sum < target) {
                ++j;
            } else {
                if (arr[j] != arr[k]) {
                    int left_count = 1;
                    int right_count = 1;

                    while (j < arr.size() - 1 && arr[j] == arr[j + 1]) {
                        ++left_count;
                        ++j;
                    }

                    while (k > 0 && arr[k] == arr[k - 1]) {
                        ++right_count;
                        --k;
                    }

                    ans += left_count * right_count;
                    ans %= MOD;
                    ++j;
                    --k;
                } else {
                    ans += (k - j + 1) * (k - j) / 2;
                    ans %= MOD;
                    break;
                }
            }
        }
    }

    return ans;
}

int main() {
    std::vector<int> arr = {1, 2, 2, 3, 4};
    int target = 6;
    std::cout << threeSumMulti(arr, target) << std::endl;

    return 0;
}
