class Solution {
    pub fn minMalwareSpread(&self, graph: Vec<Vec<i32>>, initial: Vec<i32>) -> i32 {
        let n = graph.len();
        let mut res = 0;
        let mut minSize = i32::MAX;
        let mut color: Vec<i32> = vec![i32::MIN; n];
        let mut colors = 0;

        for i in 0..n {
            if color[i] == i32::MIN {
                let mut q = Vec::new();
                q.push(i as i32);
                color[i as i32] = colors;

                while !q.is_empty() {
                    let t = q.pop().unwrap();
                    for j in 0..n {
                        if graph[t as usize][j as usize] == 1 && color[j as usize] == i32::MIN {
                            q.push(j as i32);
                            color[j as usize] = colors;
                        }
                    }
                }
