#include <iostream>
#include <vector>
#include <unordered_map>
#include <algorithm>

int largestComponentSize(std::vector<int>& nums, int k) {
    std::unordered_map<int, int> prime_factors;
    std::vector<int> primes;

    // Find all prime numbers up to k
    for (int i = 2; i <= k; ++i) {
        if (prime_factors.find(i) == prime_factors.end()) {
            primes.push_back(i);
            prime_factors[i] = i;
        }
    }

    std::vector<std::vector<int>> graph(primes.size());
    std::vector<int> visited(primes.size(), 0);

    for (int num : nums) {
        int prime = prime_factors[num];
        graph[prime].push_back(num);
        if (num != prime) {
            graph[num].push_back(prime);
        }
    }

    int count = 0;
    for (int num : nums) {
        count = std::max(count, dfs(num, visited, graph));
    }

    return count;
}

int dfs(int node, std::vector<int>& visited, std::vector<std::vector<int>>& graph) {
    if (visited[node]) {
        return 0;
    }
    visited[node] = 1;

    int size = 1;
    for (int neighbor : graph[node]) {
        size += dfs(neighbor, visited, graph);
    }
    return size;
}
