)

func canReorderArray(arr []int) bool {
	count := make(map[int]int)
	for _, num := range arr {
		count[num]++
	}
	sort.Ints(arr)
	for _, num := range arr {
		if count[num] == 0 {
			continue
		}
		if count[2*num] > 0 {
			count[num]--
			count[2*num]--
		} else {
			return false
		}
	}
	return true
}

func main() {
	arr := []int{1, 2, 3, 4}
	if canReorderArray(arr) {
		fmt.Println("Yes")
	} else {
		fmt.Println("No")
	}
}
