fn can_reorder_array(arr: &Vec<i32>) -> bool {
    let mut count = HashMap::new();
    for &num in arr.iter() {
        count.entry(num).and_modify(|c| *c += 1).or_insert(1);
    }
    arr.sort_unstable();
    for &num in arr.iter() {
        if count.get(&num).unwrap_or(&0) == 0 {
            continue;
        }
        if count.get(&num * 2).unwrap_or(&0) > 0 {
            count.entry(num).and_modify(|c| *c -= 1).or_insert(0);
            count.entry(num * 2).and_modify(|c| *c -= 1).or_insert(0);
        } else {
            return false;
        }
    }
    true
}

