import java.util.*;

public class Solution {
    public int numSquarefulPerms(int[] nums) {
        // Use a set to store unique elements and a counter to count occurrences
        Set<Integer> keySet = new HashSet<>();
        Map<Integer, Integer> counter = new HashMap<>();

        // Initialize the set and counter
        for (int num : nums) {
            keySet.add(num);
            counter.put(num, counter.getOrDefault(num, 0) + 1);
        }

        // Use a recursive function to count the number of permutations
        int result = dfs(0, keySet, counter);
        return result;
    }

    private int dfs(int idx, Set<Integer> keySet, Map<Integer, Integer> counter) {
        if (idx == keySet.size()) {
            return 1;
        }

        int count = 0;
        for (int key : keySet) {
            if (counter.get(key) > 0 && (idx == 0 || isSquare(nums[idx - 1] + key))) {
                counter.put(key, counter.get(key) - 1);
                nums[idx] = key;
                count += dfs(idx + 1, keySet, counter);
                counter.put(key, counter.get(key) + 1);
            }
        }
        return count;
    }

    // Helper function to check if a number is a square
    private boolean isSquare(int num) {
        return (int) Math.sqrt(num) * (int) Math.sqrt(num) == num;
    }
