public int findJudge(int n, int[][] trust) {
    int[] trust_counts = new int[n + 1];
    for (int[] pair : trust) {
        trust_counts[pair[0]]--;
        trust_counts[pair[1]]++;
    }
    for (int i = 1; i <= n; i++) {
        if (trust_counts[i] == n - 1) {
            return i;
        }
    }
    return -1;
}
