int maxTurbulenceSize(std::vector<std::vector<int>>& grid) {
    int n = grid.size();
    int result = 1;
    int i = 0;

    while (i < n - 1) {
        if (grid[i][0] == grid[i + 1][0]) {
            i += 1;
            continue;
        }

        int j = i + 1;
        while (j < n - 1 && (grid[j][0] > grid[j + 1][0] != grid[j - 1][0] > grid[j][0])) {
            j += 1;
        }

        result = std::max(result, j - i + 1);
        i = j;
    }

    return result;
}
