std::vector<int> interval_intersection(const std::vector<std::pair<int, int>>& firstList, const std::vector<std::pair<int, int>>& secondList) {
    std::vector<int> result;

    int i = 0, j = 0;

    while (i < firstList.size() && j < secondList.size()) {
        int start = std::max(firstList[i].first, secondList[j].first);
        int end = std::min(firstList[i].second, secondList[j].second);

        if (start <= end) {
            result.push_back(start);
            result.push_back(end);
        }

        if (firstList[i].second < secondList[j].second) {
            i++;
        } else {
            j++;
        }
    }

    return result;
}

int main() {
    std::vector<std::pair<int, int>> firstList = {{1, 2}, {3, 4}, {5, 6}};
    std::vector<std::pair<int, int>> secondList = {{1, 2}, {3, 4}, {5, 6}, {7, 8}};

    std::vector<int> result = interval_intersection(firstList, secondList);

    for (int i : result) {
        std::cout << i << " ";
    }

    return 0;
}
