int goodSubarrays(std::vector<std::vector<int>>& nums, int k) {
    int count = 0;
    for (int i = 0; i < nums.size(); ++i) {
        std::unordered_map<int, int> frequency;
        for (int j = i; j < nums.size(); ++j) {
            frequency[nums[j]]++;
            if (frequency.size() > k) break;
            if (frequency.size() == k) count++;
        }
    }
    return count;
}
