import java.util.*;
import java.util.stream.Collectors;

public class Solution {
    public boolean canPartitionKSubsets(int[] nums, int k) {
        int sum = Arrays.stream(nums).sum();
        if (sum % k != 0) return false;
        int target = sum / k;
        Arrays.sort(nums);
        return canPartitionKSubsetsHelper(nums, target, 0, new boolean[nums.length], new boolean[nums.length], 0);
    }

    private boolean canPartitionKSubsetsHelper(int[] nums, int target, int index, boolean[] visited, boolean[] used, int sum) {
        if (sum == target) {
            return true;
        }
        if (index == nums.length) {
            return false;
        }
        for (int i = 0; i < nums.length; i++) {
            if (!visited[i] && !used[i]) {
                visited[i] = true;
                used[i] = true;
                if (canPartitionKSubsetsHelper(nums, target, index + 1, visited, used, sum + nums[i])) {
                    return true;
                }
                used[i] = false;
                visited[i] = false;
            }
        }
        return false;
    }
}
