    vector<int> in_degree(n + 1, 0);
    vector<vector<int>> graph(n + 1);

    for (auto& relation : relations) {
        graph[relation[0]].push_back(relation[1]);
        in_degree[relation[1]]++;
    }

    queue<int> q;
    for (int i = 1; i <= n; i++) {
        if (in_degree[i] == 0) {
            q.push(i);
