import java.util.*;

public class Solution {
    public int minimumSemesters(int n, List<List<Integer>> relations) {
        // Create an adjacency list representation of the graph
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i <= n; i++) {
            graph.add(new ArrayList<>());
        }

        // Add edges to the graph
        for (List<Integer> relation : relations) {
            graph.get(relation.get(0)).add(relation.get(1));
        }

        // Initialize the in-degree of each node
        int[] inDegree = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            inDegree[i] = 0;
        }

        // Find the nodes with zero in-degree
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 1; i <= n; i++) {
            if (inDegree[i] == 0) {
                queue.add(i);
            }
        }

        // Perform the minimum number of semesters
        int semesters = 0;
        while (!queue.isEmpty()) {
            int size = queue.size();
            semesters++;
            while (size-- > 0) {
                int course = queue.poll();
                n--;

                // Remove the adjacent nodes with zero in-degree
                for (int next : graph.get(course)) {
                    if (--inDegree[next] == 0) {
                        queue.add(next);
                    }
                }
            }
        }

        // Check if all nodes have been processed
        return n == 0 ? semesters : -1;
    }
}
