#include <iostream>
#include <vector>

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

bool btreeGameWinningMove(TreeNode* root, int n, int x) {
    // Function to count the number of nodes in a subtree
    int countNodes(TreeNode* node) {
        if (!node) return 0;
        return countNodes(node->left) + countNodes(node->right) + 1;
    }

    // Function to find a node with a given value
    TreeNode* findNode(TreeNode* node, int x) {
        if (!node) return nullptr;
        if (node->val == x) return node;
        return findNode(node->left, x) || findNode(node->right, x);
    }

    // Find the node with the given value
    TreeNode* xNode = findNode(root, x);

    // Count the number of nodes in the left subtree of the xNode
    int leftNodes = countNodes(xNode->left);

    // Count the number of nodes in the right subtree of the xNode
    int rightNodes = countNodes(xNode->right);

    // Count the number of nodes in the parent of the xNode
    int parentNodes = n - leftNodes - rightNodes - 1;

    // Return true if the maximum of the three counts is greater than n/2
    return max(max(leftNodes, rightNodes), parentNodes) > n / 2;
}

