// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

int maxLevelSum(TreeNode* root) {
    if (!root) return 0;

    std::vector<TreeNode*> q;
    int level = 0, max_sum = INT_MIN, result_level = 0;

    while (q.size()) {
        int qlen = q.size();
        int sum = 0;

        for (int i = 0; i < qlen; ++i) {
            TreeNode* temp = q[i];
            sum += temp->val;

            if (temp->left) q.push_back(temp->left);
            if (temp->right) q.push_back(temp->right);
        }

        if (sum > max_sum) {
            max_sum = sum;
            result_level = level;
        }

        level++;
    }

    return result_level;
}
