import java.util.HashMap;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    public static void main(String[] args) {
        String[] phrases = {"writing code", "code rocks"};
        Set<String> result = beforeAndAfterPuzzles(phrases);
        System.out.println(result);
    }

    private static Set<String> beforeAndAfterPuzzles(String[] phrases) {
        HashMap<String, Set<String>> firstWordMap = new HashMap<>();
        Set<String> result = new HashSet<>();

        for (String phrase : phrases) {
            String firstWord = phrase.split(" ")[0];
            firstWordMap.putIfAbsent(firstWord, new HashSet<>());
            firstWordMap.get(firstWord).add(phrase);
        }

        for (String phrase : phrases) {
            String lastWord = phrase.split(" ")[-1];
            if (lastWord != null && lastWord.length() > 0) {
                if (firstWordMap.containsKey(lastWord)) {
                    for (String curPhrase : firstWordMap.get(lastWord)) {
                        if (!phrase.equals(curPhrase)) {
                            result.add(phrase + curPhrase.substring(curPhrase.indexOf(' ')));
                        }
                    }
                }
            }
        }

        return result;
    }
}
```



