#include <vector>
#include <algorithm>

std::vector<int> shortestDistance(const std::vector<int>& colors, const std::vector<std::vector<int>>& queries) {
    std::vector<int> result(queries.size());
    std::vector<std::vector<int>> positions(3);

    for (int i = 0; i < colors.size(); ++i) {
        positions[colors[i] - 1].push_back(i);
    }

    for (const auto& query : queries) {
        int index_positions = positions[query[1] - 1].size();

        if (index_positions == 0) {
            result[queries.size() - 1] = -1;
        } else {
            int dist = std::numeric_limits<int>::max();

            for (int pos : positions[query[1] - 1]) {
                dist = std::min(dist, std::abs(pos - query[0]));
            }

            result[queries.size() - 1] = dist;
        }
    }

    return result;
}
