)

type TreeNode struct {
	Val   int
	Left  *TreeNode
	Right *TreeNode
}

func delNodes(root *TreeNode, to_delete []int) []*TreeNode {
	forest := make([]*TreeNode, 0)
	toDeleteSet := make(map[int]bool)
	for _, val := range to_delete {
		toDeleteSet[val] = true
	}
	helper(root, true, toDeleteSet, forest)
	return forest
}

func helper(node *TreeNode, isRoot bool, toDeleteSet map[int]bool, forest []*TreeNode) {
	if node == nil {
		return
	}
	deleted := toDeleteSet[node.Val]
	if isRoot && !deleted {
		forest = append(forest, node)
	}
	node.Left = helper(node.Left, deleted, toDeleteSet, forest)
	node.Right = helper(node.Right, deleted, toDeleteSet, forest)
	if deleted {
		node = nil
	}
}

func main() {
	root := &TreeNode{
