    int* parent = new int[n + 1];
    int* rank = new int[n + 1];

    for (int i = 1; i <= n; i++) {
        parent[i] = i;
    }

    std::function<int(int)> find = [this, &parent](int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    };

    std::function<void(int, int)> unite = [this, &parent, &rank](int x, int y) {
