#include <iostream>
#include <vector>
#include <string>
#include <unordered_map>
#include <algorithm>

int stoneGameII(int n, int m) {
    std::vector<int> piles(n, 0);
    for (int i = 0; i < n; ++i) {
        piles[i] = i + 1;
    }

    // Use a cache to store the results of the recursive calls
    std::unordered_map<std::pair<int, int>, int> cache;
    int result = stoneGameIIHelper(piles, 0, m, cache);

    return result;
}

int stoneGameIIHelper(const std::vector<int>& piles, int idx, int m, std::unordered_map<std::pair<int, int>, int>& cache) {
    if (idx + 2 * m >= piles.size()) {
        return piles[idx];
    }

    if (cache.find(std::make_pair(idx, m)) != cache.end()) {
        return cache[std::make_pair(idx, m)];
    }

    int max_value = 0;
    for (int x = 1; x <= 2 * m; ++x) {
        max_value = std::max(max_value, piles[idx] - stoneGameIIHelper(piles, idx + x, m, cache));
    }

    cache[std::make_pair(idx, m)] = max_value;
    return max_value;
}
