                count++;
            }
        }
    }
    return count;
}

private bool dfs(int[][] grid, int i, int j) {
    if (i < 0 || j < 0 || i >= grid.Length || j >= grid[0].Length) {
        return false;
    }

    if (grid[i][j] == 1) {
        return true;
    }

    grid[i][j] = 1;

    bool up = dfs(grid, i - 1, j);
    bool down = dfs(grid, i + 1, j);
    bool left = dfs(grid, i, j - 1);
    bool right = dfs(grid, i, j + 1);

    return up && down && left && right;
}
