import java.util.*;

public class Solution {
    public int findTheCity(int n, int[][] edges, int distanceThreshold) {
        // Create a 2D array to store distances between cities
        int[][] distance = new int[n][n];

        // Initialize all distances to infinity
        for (int i = 0; i < n; i++) {
            Arrays.fill(distance[i], Integer.MAX_VALUE);
        }

        // Fill the distance matrix with the given edge weights
        for (int[] edge : edges) {
            distance[edge[0]][edge[1]] = edge[2];
            distance[edge[1]][edge[0]] = edge[2];
        }

        // Set the distance to itself to 0
        for (int i = 0; i < n; i++) {
            distance[i][i] = 0;
        }

        // Use Floyd-Warshall algorithm to find the shortest path between all pairs of cities
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < n; j++) {
                    distance[i][j] = Math.min(distance[i][j], distance[i][k] + distance[k][j]);
                }
            }
        }

        // Find the city with the minimum number of reachable cities within the given distance threshold
        int res = 0, minReachable = n;
        for (int i = 0; i < n; i++) {
            int reachable = 0;
            for (int j = 0; j < n; j++) {
                if (distance[i][j] <= distanceThreshold) {
                    reachable++;
                }
            }
            if (reachable <= minReachable) {
                minReachable = reachable;
                res = i;
            }
        }
        return res;
    }
}
