int maxEqualFreq(std::vector<int>& nums) {
    std::unordered_map<int, int> count;
    std::unordered_map<int, int> freq;
    int max_len = 0, max_freq = 0;
    for (int i = 0; i < nums.size(); ++i) {
        count[nums[i]] = count.get(nums[i], 0) + 1;
        freq[count[nums[i]] - 1] = freq.get(count[nums[i]] - 1, 0) - 1;
        freq[count[nums[i]]] = freq.get(count[nums[i]], 0) + 1;

        max_freq = std::max(max_freq, count[nums[i]]);
        if (max_freq * (i + 1) == i || max_freq * (freq.get(max_freq - 1, 0) + 1) + (max_freq - 1) * freq.get(max_freq - 1, 0) == i) {
            max_len = i + 1;
        }
    }
    return max_len;
}

