int minJumps(std::vector<int>& arr) {
    int n = arr.size();
    if (n <= 1) return 0;

    std::unordered_map<int, std::vector<int>> value_indices;
    for (int i = 0; i < n; ++i) {
        value_indices[arr[i]].push_back(i);
    }

    std::queue<int> q;
    std::vector<bool> visited(n, false);

    q.push(0);
    visited[0] = true;
    int steps = 0;

    while (!q.empty()) {
        int size = q.size();

        for (int i = 0; i < size; ++i) {
            int index = q.front();
            q.pop();

            if (index == n - 1) return steps;

            if (index > 0 && !visited[index - 1]) {
                q.push(index - 1);
                visited[index - 1] = true;
            }

            if (index < n - 1 && !visited[index + 1]) {
                q.push(index + 1);
                visited[index + 1] = true;
            }

            for (int neighbor : value_indices[arr[index]]) {
                if (!visited[neighbor]) {
                    q.push(neighbor);
                    visited[neighbor] = true;
                }
            }

            value_indices[arr[index]].clear();
        }

        ++steps;
    }

    return -1;
}
