import java.util.*;
import java.util.concurrent.PriorityQueue;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.ConcurrentHashMap;

public class Solution {
    public int minJumps(int[] arr) {
        int n = arr.length;
        if (n <= 1) return 0;

        Map<Integer, List<Integer>> valueIndices = new ConcurrentHashMap<>();
        for (int i = 0; i < n; ++i) {
            valueIndices.put(arr[i], new ArrayList<>());
            valueIndices.get(arr[i]).add(i);
        }

        PriorityQueue<Integer> q = new PriorityQueue<>();
        boolean[] visited = new boolean[n];

        q.offer(0);
        visited[0] = true;
        int steps = 0;

        while (!q.isEmpty()) {
            int size = q.size();

            for (int i = 0; i < size; ++i) {
                int index = q.poll();

                if (index == n - 1) return steps;

                if (index > 0 && !visited[index - 1]) {
                    q.offer(index - 1);
                    visited[index - 1] = true;
                }

                if (index < n - 1 && !visited[index + 1]) {
                    q.offer(index + 1);
                    visited[index + 1] = true;
                }

                for (int neighbor : valueIndices.get(arr[index])) {
                    if (!visited[neighbor]) {
                        q.offer(neighbor);
                        visited[neighbor] = true;
                    }
                }

                valueIndices.get(arr[index]).clear();
            }

            ++steps;
        }

        return -1;
    }
}
