std::string largestMultipleOfThree(std::vector<int>& digits) {
    std::vector<int> sortedDigits(digits);
    std::sort(sortedDigits.begin(), sortedDigits.end(), std::greater<int>());

    int sumDigits = 0;
    for (int digit : sortedDigits) {
        sumDigits += digit;
    }

    if (sumDigits % 3 == 0) {
        return std::to_string(sumDigits);
    }

    std::unordered_map<int, std::vector<int>> mod;
    for (int digit : sortedDigits) {
        mod[digit % 3].push_back(digit);
    }

    if (sumDigits % 3 == 1) {
        if (!mod[1].empty()) {
            mod[1].pop_back();
        } else {
            mod[2].pop_back();
            mod[2].pop_back();
        }
    } else {
        if (!mod[2].empty()) {
            mod[2].pop_back();
        } else {
            mod[1].pop_back();
            mod[1].pop_back();
        }
    }

    std::string result = "";
    for (const auto& pair : mod) {
        for (int digit : pair.second) {
            result += std::to_string(digit);
        }
    }
    std::sort(result.begin(), result.end(), std::greater<char>());

    return result;
}

int main() {
    std::vector<int> digits = {8, 1, 9};
    std::cout << largestMultipleOfThree(digits) << std::endl;
    return 0;
}
