#include <iostream>
#include <vector>
#include <queue>

int minCost(std::vector<std::vector<int>> grid) {
    int m = grid.size(), n = grid[0].size();
    int cost = 0;

    std::vector<std::vector<int>> visited(m, std::vector<int>(n, 1000000));
    std::queue<std::pair<int, int>> q;
    visited[0][0] = 0;

    while (!q.empty()) {
        int y = q.front().first;
        int x = q.front().second;
        q.pop();
        if (y == m - 1 && x == n - 1) {
            cost = visited[y][x];
            break;
        }

        int dx[] = {1, 0, -1, 0};
        int dy[] = {0, 1, 0, -1};

        for (int dir = 0; dir < 4; ++dir) {
            int newY = y + dy[dir];
            int newX = x + dx[dir];
            if (0 <= newY && newY < m && 0 <= newX && newX < n) {
                int newCost = visited[y][x] + (1 - (grid[y][x] - 1) % 2);
                if (newCost < visited[newY][newX]) {
                    visited[newY][newX] = newCost;
                    q.push({newY, newX});
                }
            }
        }
    }

    return cost;
}

int main() {
    std::vector<std::vector<int>> grid = {{1, 1, 1, 1}, {2, 2, 2, 2}, {1, 1, 1, 1}, {2, 2, 2, 2}};
    std::cout << minCost(grid) << std::endl;
    return 0;
}
