using System;
using System.Collections.Generic;

public class Main {
    public static void Main(string[] args) {
        int[][] grid = {{1, 1, 1, 1}, {2, 2, 2, 2}, {1, 1, 1, 1}, {2, 2, 2, 2}};
        Console.WriteLine(minCost(grid));
    }

    public static int minCost(int[][] grid) {
        int m = grid.Length, n = grid[0].Length;
        int cost = 0;

        int[,] visited = new int[m, n];
        Queue<(int y, int x)> q = new Queue<(int, int)>();
        visited[0, 0] = 0;

        while (q.Count > 0) {
            int y = q.Peek().y;
            int x = q.Peek().x;
            q.Dequeue();
            if (y == m - 1 && x == n - 1) {
                cost = visited[y, x];
                break;
            }

            int[] dx = {1, 0, -1, 0};
            int[] dy = {0, 1, 0, -1};

            for (int dir = 0; dir < 4; ++dir) {
                int newY = y + dy[dir];
                int newX = x + dx[dir];
                if (0 <= newY && newY < m && 0 <= newX && newX < n) {
                    int newCost = visited[y, x] + (1 - (grid[y, x] - 1) % 2);
                    if (newCost < visited[newY, newX]) {
                        visited[newY, newX] = newCost;
                        q.Enqueue((newY, newX));
                    }
                }
            }
        }

        return cost;
    }
}
