void dfs(int node, int parent, int t, int target, const std::unordered_map<int, std::vector<int>>& graph, double prob, std::vector<double>& ans) {
    if (t == 0) {
        if (node == target) {
            ans[0] += prob;
        }
        return;
    }

    bool has_child = false;
    for (const auto& neighbor : graph[node]) {
        if (neighbor != parent) {
            has_child = true;
            dfs(neighbor, node, t - 1, target, graph, prob / (graph[node].size() - (1 if node != 1 else 0)), ans);
        }
    }

    if (!has_child && node == target) {
        ans[0] += prob;
    }
}
