int minTimeToVisitAllPoints(std::vector<std::vector<int>> points) {
    int time = 0;
    for (int i = 1; i < points.size(); ++i) {
        int dx = std::abs(points[i][0] - points[i - 1][0]);
        int dy = std::abs(points[i][1] - points[i - 1][1]);
        time += std::max(dx, dy);
    }
    return time;
}

