int countSquares(const std::vector<std::vector<int>>& matrix) {
    int m = matrix.size(), n = matrix[0].size(), ans = 0;
    std::vector<std::vector<int>> dp(m, std::vector<int>(n, 0));
    for (int i = 0; i < m; ++i) {
        for (int j = 0; j < n; ++j) {
            if (i == 0 || j == 0) {
                dp[i][j] = matrix[i][j];
            } else if (matrix[i][j]) {
                dp[i][j] = std::min(dp[i-1][j-1], dp[i-1][j], dp[i][j-1]) + 1;
            }
            ans += dp[i][j];
        }
    }
    return ans;
}

