    public int CountSquares(int[][] matrix) {
        int m = matrix.Length, n = matrix[0].Length, ans = 0;
        int[][] dp = new int[m][n];
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i == 0 || j == 0) {
                    dp[i][j] = matrix[i][j];
                } else if (matrix[i][j]) {
                    dp[i][j] = Math.Min(dp[i-1][j-1], dp[i-1][j], dp[i][j-1]) + 1;
                }
                ans += dp[i][j];
            }
        }
        return ans;
    }
}

public class Main {
    public static void Main(string[] args) {
        int[][] matrix = {{-1, -8, 0, 5, -9}};
        Console.WriteLine(new Solution().CountSquares(matrix));
    }
}
