#include <iostream>
#include <string>
#include <unordered_map>
#include <vector>

std::vector<std::vector<std::string>> displayTable(const std::vector<std::vector<std::string>>& orders) {
    std::unordered_map<int, std::unordered_map<std::string, int>> tables;
    std::unordered_set<std::string> foodSet;

    for (const auto& order : orders) {
        int tableNumber = std::stoi(order[1]);
        std::string foodItem = order[2];
        tables[tableNumber][foodItem] += 1;
        foodSet.insert(foodItem);
    }

    std::vector<std::string> foodList = { "Table", "Beef Burrito", "Ceviche", "Fried Chicken", "Water" };
    std::vector<std::vector<std::string>> result;

    for (const auto& table : tables) {
        std::vector<std::string> row = { std::to_string(table.first) };
        for (const auto& food : foodList) {
            row.push_back(std::to_string(table.second[food]));
        }
        result.push_back(row);
    }

    return result;
}

int main() {
    std::vector<std::vector<std::string>> orders = { { "David", "3", "Ceviche" }, { "Corina", "10", "Beef Burrito" }, { "David", "3", "Fried Chicken" }, { "Carla", "5", "Water" }, { "Carla", "5", "Ceviche" }, { "Rous", "3", "Ceviche" } };
    std::vector<std::vector<std::string>> result = displayTable(orders);
    for (const auto& row : result) {
        for (const auto& item : row) {
            std::cout << item << " ";
        }
        std::cout << std::endl;
    }

    return 0;
}
