bool isPossibleDivide(const std::vector<int>& nums, int k) {
    std::unordered_map<int, int> counts;
    for (int num : nums) {
        counts[num]++;
    }

    for (int i = 0; i < k - 1; i++) {
        for (int key = 0; key < counts.size(); key++) {
            int count = counts[key];
            if (count > 0) {
                int target = key + i + 1;
                if (counts.find(target) == counts.end() || counts[target] < count) {
                    return false;
                }
                counts[target] -= count;
            }
        }
    }
    return true;
}

int main() {
    std::vector<int> nums = {1, 1, 1, 1, 1};
    int k = 3;
    std::cout << isPossibleDivide(nums, k) << std::endl;
    return 0;
}
