fn is_possible_divide(nums: &Vec<i32>, k: i32) -> bool {
    let mut counts: HashMap<i32, i32> = HashMap::new();
    for num in nums {
        *counts.entry(*num).or_insert(0) += 1;
    }

    for i in 0..(k - 1) {
        for key in counts.keys() {
            let count = counts.get(&key).unwrap();
            if *count > 0 {
                let target = key + i + 1;
                if !counts.contains_key(&target) || counts.get(&target).unwrap() < *count {
                    return false;
                }
                *counts.get_mut(&target).unwrap() -= *count;
            }
        }
    }
    true
}

