import java.util.*;
import java.util.stream.*;

public class Solution {
    public boolean isPossibleDivide(int[] nums, int k) {
        Map<Integer, Integer> counts = new HashMap<>();
        for (int num : nums) {
            counts.put(num, counts.getOrDefault(num, 0) + 1);
        }

        for (int i = 0; i < k - 1; i++) {
            for (Map.Entry<Integer, Integer> entry : counts.entrySet()) {
                int count = entry.getValue();
                if (count > 0) {
                    int target = entry.getKey() + i + 1;
                    if (!counts.containsKey(target) || counts.get(target) < count) {
                        return false;
                    }
                    counts.put(target, counts.get(target) - count);
                }
            }
        }
        return true;
    }

    public static void main(String[] args) {
        int[] nums = {1, 1, 1, 1, 1};
        int k = 3;
        System.out.println(new Solution().isPossibleDivide(nums, k));
    }
