#include <iostream>
#include <vector>

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode(int x) : val(x), left(NULL), right(NULL) {}
};

bool isValidSequence(TreeNode* root, const std::vector<int>& arr, int index = 0) {
    if (!root || index >= arr.size() || arr[index] != root->val) {
        return false;
    }
    if (!root->left && !root->right) {
        return index == arr.size() - 1;
    }
    return isValidSequence(root->left, arr, index + 1) || isValidSequence(root->right, arr, index + 1);
}

int main() {
    TreeNode* root = new TreeNode(0);
    root->left = new TreeNode(1);
    root->right = new TreeNode(0);
    root->right->left = new TreeNode(1);
    root->right->right = new TreeNode(0);
    root->right->right->left = new TreeNode(1);
    root->right->right->right = new TreeNode(0);

    std::vector<int> arr = {0, 1, 0, 1};
    std::cout << isValidSequence(root, arr) << std::endl;

    return 0;
}
