// Function to remove leaf nodes from a binary tree
void removeLeafNodes(std::vector<int>& startTime, std::vector<int>& endTime, int queryTime) {
    // Base case: If the tree is empty, return
    if (startTime.empty() || endTime.empty()) {
        return;
    }

    // Remove leaf nodes from the left subtree
    removeLeafNodes(startTime, startTime, queryTime);

    // Remove leaf nodes from the right subtree
    removeLeafNodes(endTime, endTime, queryTime);

    // Check if the current node is a leaf node and its value matches the query time
    if (startTime.empty() && endTime.empty() && queryTime == startTime[0]) {
        // If so, remove the node
        startTime.erase(startTime.begin());
        endTime.erase(endTime.begin());
    }
}

