import java.util.*;

public class Solution {
    public List<Boolean> checkIfPrerequisite(int numCourses, List<List<Integer>> prerequisites, List<List<Integer>> queries) {
        // Create an adjacency matrix to represent the graph
        boolean[][] adjMatrix = new boolean[numCourses][numCourses];
        for (List<Integer> pre : prerequisites) {
            adjMatrix[pre.get(0)][pre.get(1)] = true;
        }

        // Perform depth-first search to find the prerequisites
        for (int k = 0; k < numCourses; k++) {
            for (int i = 0; i < numCourses; i++) {
                for (int j = 0; j < numCourses; j++) {
                    adjMatrix[i][j] = adjMatrix[i][j] || (adjMatrix[i][k] && adjMatrix[k][j]);
                }
            }
        }

        // Return the result of the queries
        List<Boolean> results = new ArrayList<>();
        for (List<Integer> query : queries) {
            results.add(adjMatrix[query.get(0)][query.get(1)]);
        }
        return results;
    }
}
