int max_size_slices(std::vector<int> slices) {
    int n = slices.size() / 3;
    std::vector<std::vector<int>> memo1(n + 1, std::vector<int>(n + 1, -1));
    std::vector<std::vector<int>> memo2(n + 1, std::vector<int>(n + 1, -1));

    return std::max(max_sum(slices, 0, slices.size() - 1, n, memo1),
                    max_sum(slices, 1, slices.size(), n, memo2));
}

int max_sum(std::vector<int> slices, int start, int end, int n, std::vector<std::vector<int>>& memo) {
    if (n == 0) return 0;
    if (end - start + 1 < n * 2) return -std::numeric_limits<int>::max();
    if (memo[start][n] != -1) return memo[start][n];

    int pick = max_sum(slices, start + 2, end, n - 1, memo) + slices[start];
    int not_pick = max_sum(slices, start + 1, end, n, memo);

    memo[start][n] = std::max(pick, not_pick);
    return memo[start][n];
}
