class Solution {
    public List<Integer> minSubsequence(int[] nums) {
        List<Integer> result = new ArrayList<Integer>();
        Arrays.sort(nums);
        int totalSum = 0, currentSum = 0;
        for (int num : nums) {
            totalSum += num;
        }
        for (int i = nums.length - 1; i >= 0; i--) {
            currentSum += nums[i];
