package main

import (
	"fmt"
	"sort"
)

func buildArray(target []int, n int) []string {
	result := make([]string, n)
	current := 1
	for _, num := range target {
		for current < num {
			result[current] = "Push"
			result[current+1] = "Pop"
			current += 2
		}
		result[current] = "Push"
		current++
	}
	return result
}

