def buildArray(target: Array[Int], n: Int): Array[String] = {
    val result = Array.ofDim[String](n)
    var current = 1
    for (num <- target) {
        while (current < num) {
            result(current) = "Push"
            result(current + 1) = "Pop"
            current += 2
        }
        result(current) = "Push"
        current += 1
    }
    result
}

