public int minSubarray(int[] nums, int p) {
    int n = nums.length, res = n, need = 0, cur = 0;
    for (int num : nums) {
        need = (need + num) % p;
    }
    if (need == 0) return 0;
    Map<Integer, Integer> last_seen = new HashMap<>();
    last_seen.put(0, -1);
    for (int i = 0, num : nums) {
        cur = (cur + num) % p;
        last_seen.put(cur, i);
        res = Math.min(res, i - last_seen.get(((cur - need + p) % p) + p));
    }
    return res < n ? res : -1;
}
