public int maxProductPath(int[][] grid) {
    int m = grid.length, n = grid[0].length, mod = 1000000007;
    int[][][] dp = new int[m][n][2];
    dp[0][0][0] = grid[0][0];
    dp[0][0][1] = grid[0][0];
    for (int i = 1; i < m; ++i) {
        dp[i][0][0] = grid[i][0] * dp[i - 1][0][0];
        dp[i][0][1] = grid[i][0] * dp[i - 1][0][1];
    }
    for (int j = 1; j < n; ++j) {
        dp[0][j][0] = grid[0][j] * dp[0][j - 1][0];
        dp[0][j][1] = grid[0][j] * dp[0][j - 1][1];
    }
    for (int i = 1; i < m; ++i) {
        for (int j = 1; j < n; ++j) {
            if (grid[i][j] < 0) {
                dp[i][j][0] = Math.max(dp[i - 1][j][1] * grid[i][j], dp[i][j - 1][1] * grid[i][j]);
                dp[i][j][1] = Math.min(dp[i - 1][j][0] * grid[i][j], dp[i][j - 1][0] * grid[i][j]);
            } else {
                dp[i][j][0] = Math.min(dp[i - 1][j][0] * grid[i][j], dp[i][j - 1][0] * grid[i][j]);
                dp[i][j][1] = Math.max(dp[i - 1][j][1] * grid[i][j], dp[i][j - 1][1] * grid[i][j]);
            }
        }
    }
    return dp[m - 1][n - 1][1] < 0 ? -1 : dp[m - 1][n - 1][1];
}
