int busiestServers(int k, std::vector<int> arrival, std::vector<int> load) {
    std::vector<int> server_status(k, -1);
    std::vector<int> server_request_count(k, 0);

    for (int i = 0; i < arrival.size(); i++) {
        int index = i % k;
        for (int j = 0; j < k; j++) {
            if (server_status[index] <= arrival[i]) {
                server_status[index] = arrival[i] + load[i];
                server_request_count[index]++;
                break;
