int getMinDistSum(const std::vector<std::vector<int>>& positions) {
    int x = 0, y = 0;
    int n = positions.size();
    for (const auto& pos : positions) {
        x += pos[0];
        y += pos[1];
    }
    x /= n;
    y /= n;
    return x;
}

int main() {
    std::vector<std::vector<int>> positions = {{1, 2}, {3, 4}, {5, 6}};
    std::cout << getMinDistSum(positions) << std::endl;
    return 0;
}
