def numberOfFairs(nums):
    even_sum = 0
    odd_sum = 0
    l_even = 0
    l_odd = 0
    count = 0

    # Calculate the sum of even and odd numbers
    for num in nums:
        if num % 2 == 0:
            even_sum += num
        else:
            odd_sum += num

    # Iterate through the array and count the number of fair partitions
    for i in range(len(nums)):
        if i % 2 == 0:
            even_sum -= nums[i]
            if l_even + odd_sum == l_odd + even_sum:
                count += 1
            l_even += nums[i]
        else:
            odd_sum -= nums[i]
            if l_even + odd_sum == l_odd + even_sum:
                count += 1
            l_odd += nums[i]

    return count
