import java.util.*;

public class Main {
    public static void main(String[] args) {
        List<Integer> list1 = Arrays.asList(0, 1, 2, 3, 4, 5);
        int a = 3, b = 4;
        List<Integer> list2 = Arrays.asList(1000000, 1000001, 1000002);

        System.out.println(minCost(list1, a, b));
        System.out.println(minCost(list2, a, b));
    }

    private static int minCost(List<Integer> cuts, int a, int b) {
        cuts.add(0);
        cuts.add(cuts.get(cuts.size() - 1) + 1);
        cuts.sort(Comparator.naturalOrder());

        int size = cuts.size();
        int[][] dp = new int[size][size];

        for (int len = 2; len < size; len++) {
            for (int i = 0; i < size - len; i++) {
                int j = i + len;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i + 1; k < j; k++) {
                    dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k][j] + cuts.get(j) - cuts.get(i));
                }
            }
        }

        return dp[0][size - 1];
    }
}
