fn min_cost(n: i32, cuts: Vec<i32>) -> i32 {
    cuts.insert(0, 0);
    cuts.push(n + 1);
    cuts.sort();

    let size = cuts.len();
    let mut dp = vec![vec![0; size]; size];

    for len in 2..size {
        for i in 0..size - len {
            let j = i + len;
            dp[i][j] = i32::MAX;
            for k in i + 1..j {
                dp[i][j] = dp[i][j].min(dp[i][k] + dp[k][j] + cuts[j] - cuts[i]);
            }
        }
    }

    dp[0][size - 1]
}

