    private static int minCost(List<Integer> cuts, int a, int b) {
        cuts.add(0);
        cuts.add(cuts.get(cuts.size() - 1) + 1);
        cuts.sort(Comparator.naturalOrder());

        int size = cuts.size();
        int[][] dp = new int[size][size];

        for (int len = 2; len < size; len++) {
            for (int i = 0; i < size - len; i++) {
                int j = i + len;
                dp[i][j] = Integer.MAX_VALUE;
                for (int k = i + 1; k < j; k++) {
                    dp[i][j] = Math.min(dp[i][j], dp[i][k] + dp[k][j] + cuts.get(j) - cuts.get(i));
                }
            }
        }

        return dp[0][size - 1];
    }
