#include <iostream>
#include <vector>
#include <algorithm>

int waysToSplit(std::vector<int> nums) {
    int MOD = 1000000007;
    int n = nums.size();
    std::vector<int> prefixSum(n + 1);
    for (int i = 0; i < n; ++i) {
        prefixSum[i + 1] = prefixSum[i] + nums[i];
    }

    int ans = 0;
    int left = 0, right = 0;
    for (int mid = 1; mid < n - 1; ++mid) {
        while (left + 1 < mid && prefixSum[left + 1] * 2 <= prefixSum[mid]) {
            ++left;
        }
        while (right < mid || (right + 1 < n && prefixSum[right + 1] - prefixSum[mid] <= prefixSum[n] - prefixSum[right + 1])) {
            ++right;
        }
        if (right >= mid && prefixSum[mid] - prefixSum[left] <= prefixSum[right] - prefixSum[mid]) {
            ans = (ans + right - mid + 1) % MOD;
        }
    }

    return ans;
}

int main() {
    std::vector<int> nums = {1, 1, 1};
    std::cout << waysToSplit(nums) << std::endl;
    return 0;
}
