int count_trees(const std::vector<std::pair<int, int>>& pairs) {
    int nodes = pairs.size() + 1;
    std::vector<int> in_degrees(nodes, 0);
    for (const auto& pair : pairs) {
        in_degrees[pair.second]++;
    }

    int res = 1;
    for (int in_degree : in_degrees) {
        res *= in_degree;
