CREATE FUNCTION next_palindrome(num VARCHAR(255)) RETURNS VARCHAR(255)
BEGIN
    DECLARE n INT;
    SET n = LENGTH(num);
    DECLARE first_half VARCHAR(255);
    SET first_half = SUBSTRING(num, 1, FLOOR(n / 2));
    SET first_half = CONCAT(first_half, ' ');
    SET first_half = REPLACE(first_half, ' ', '');
    SET first_half = GROUP_CONCAT(first_half ORDER BY first_half ASC);
    IF first_half > SUBSTRING(num, 1, FLOOR(n / 2)) THEN
        SET second_half = SUBSTRING(first_half, 1, LENGTH(first_half) - 1);
        RETURN CONCAT(first_half, second_half);
    END IF;
    RETURN '';
END
