#include <unordered_map>
#include <vector>
using namespace std;

vector<int> distinctNumbersInSubarrays(vector<int>& nums, int k) {
    unordered_map<int, int> counts;
    vector<int> ans;
    for (int i = 0; i < nums.size(); i++) {
        counts[nums[i]]++;
        if (i >= k) {
            counts[nums[i - k]]--;
            if (counts[nums[i - k]] == 0) {
                counts.erase(nums[i - k]);
            }
        }
        if (i >= k - 1) {
            ans.push_back(counts.size());
        }
    }
    return ans;
}
```

