def distinct_numbers_in_subarrays(nums, k):
    counts = defaultdict(int)
    ans = []
    for i in range(len(nums)):
        counts[nums[i]] += 1
        if i >= k:
            counts[nums[i - k]] -= 1
            if counts[nums[i - k]] == 0:
                counts.pop(nums[i - k])
        if i >= k - 1:
            ans.append(len(counts))
