public int subsetXORSum(int[] nums) {
    int ans = 0;
    int n = nums.length;
    int max_val = 1 << n;
    for (int i = 1; i < max_val; i++) {
        int xor_total = 0;
        for (int j = 0; j < n; j++) {
            if ((i & (1 << j)) != 0) {
