    let n = dist.len();
    let mut dp = vec![vec![i32::MAX; n + 1]; n + 1];

    dp[0][0] = 0;

    for i in 0..n {
        for j in -1..=i {
            let t = (dist[i] as f64) / (speed as f64) + (j != -1 as i32) as f64;
