fn min_trio_degree(n: i32, edges: Vec<Vec<i32>>) -> i32 {
    let mut graph = HashMap::new();
    let mut degree = vec![0; n as usize + 1];

    for edge in &edges {
        let [u, v] = edge;
        graph.entry(*u).or_insert(HashMap::new()).insert(*v, true);
        graph.entry(*v).or_insert(HashMap::new()).insert(*u, true);
        degree[*u] += 1;
        degree[*v] += 1;
    }

    let mut min_degree = i32::MAX;
    for edge in &edges {
        let [u, v] = edge;
        for w in 1..=n {
            if graph.get(&u).unwrap().contains_key(&w) && graph.get(&v).unwrap().contains_key(&w) {
                min_degree = min(min_degree, degree[u] + degree[v] + degree[w] - 6);
            }
        }
    }

    min_degree
}

