    public static void main(String[] args) {
        String s = "abacbc";
        System.out.println(isSorted(s));
    }

    private static boolean isSorted(String s) {
        int n = s.length();
        int[] fact = new int[n + 1];
        int[] inv = new int[n + 1];
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i;
            inv[i] = inv[i - 1] * (1000000007 - (1000000007 / i));
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            int less_than = 0;
            for (int j = i + 1; j < n; j++) {
                if (s.charAt(j) < s.charAt(i)) {
                    less_than++;
                }
            }
            ans = (ans + less_than * fact[n - i - 1]) % 1000000007;
        }
        return ans == 0;
    }
}
