public class Solution {
    public List<List<Integer>> splitPainting(int[][] segments) {
        // Initialize an empty list to store the results
        List<List<Integer>> result = new ArrayList<>();

        // Iterate over each segment in the input array
        for (int[] segment : segments) {
            // Extract the start, end, and color values from the current segment
            int start = segment[0];
            int end = segment[1];
            int color = segment[2];

            // Check if the start and end indices are already in the result list
            if (result.contains(start)) {
                // If the start index is already in the result list, update its color value
                for (List<Integer> list : result) {
                    if (list.get(1).equals(start)) {
                        list.set(2, list.get(2) + color);
                    }
                }
            } else {
                // If the start index is not in the result list, add it with the current color value
                result.add(Arrays.asList(start, color));
            }

            // Check if the end index is already in the result list
            if (result.contains(end)) {
                // If the end index is already in the result list, update its color value
                for (List<Integer> list : result) {
                    if (list.get(1).equals(end)) {
                        list.set(2, list.get(2) - color);
                    }
                }
            } else {
                // If the end index is not in the result list, add it with the current color value
                result.add(Arrays.asList(end, -color));
            }
        }

        // Return the final result list
        return result;
    }
}
