public int minSpaceWastedKResizing(int[] nums, int k) {
    int n = nums.length;
    int[] dp = new int[n + 1][k + 1];
    int[] sum_nums = new int[n + 1];
    dp[0][0] = 0;

    for (int i = 1; i <= n; i++) {
        sum_nums[i] = sum_nums[i - 1] + nums[i - 1];
        int max_val = nums[i - 1];
        for (int j = i - 1; j >= 0; j--) {
            max_val = Math.max(max_val, nums[j]);
            int waste = max_val * (i - j) - (sum_nums[i] - sum_nums[j]);
            for (int c = 0; c <= k; c++) {
                dp[i][c + 1] = Math.min(dp[i][c + 1], dp[j][c] + waste);
            }
        }
    }
    return dp[n][k];
}
