            while (taskIdx < tasksSize && tasks[taskIndices[taskIdx]][0] <= time) {
                // Add the task to the priority queue
                minHeap.push({taskIndices[taskIdx], tasks[taskIndices[taskIdx]][1]});
                // Remove the task index from the task indices array
                taskIndices[taskIdx] = NULL;
                // Increment the task index
                taskIdx++;
