int main() {
    std::vector<int> obstacles = {1, 2, 3, 2};
    std::vector<int> ans(obstacles.size(), 0);

    // Use a dynamic programming approach to find the longest obstacle course
    for (int i = 0; i < obstacles.size(); i++) {
        int index = std::lower_bound(ans.begin(), ans.end(), obstacles[i]) - ans.begin();
        ans[index] = i + 1;
        if (index == ans.size()) {
            ans.push_back(obstacles[i]);
        } else {
            ans[index] = obstacles[i];
        }
    }

    // Print the result
    for (int i = 0; i < ans.size(); i++) {
        std::cout << ans[i] << " ";
    }
    std::cout << std::endl;

    return 0;
}
