public class Main {
    public static void main(String[] args) {
        int[] obstacles = {1, 2, 3, 2};
        int[] ans = new int[obstacles.length];

        // Use a dynamic programming approach to find the longest obstacle course
        for (int i = 0; i < obstacles.length; i++) {
            int index = Arrays.binarySearch(ans, obstacles[i]);
            ans[index] = i + 1;
            if (index == ans.length) {
                ans = Arrays.copyOf(ans, ans.length + 1);
                ans[ans.length - 1] = obstacles[i];
            } else {
                ans[index] = obstacles[i];
            }
        }

        // Print the result
        for (int i = 0; i < ans.length; i++) {
            System.out.print(ans[i] + " ");
        }
        System.out.println();
    }
