function longestObstacleCourse(obstacles) {
    let ans = new Array(obstacles.length).fill(0);

    // Use a dynamic programming approach to find the longest obstacle course
    for (let i = 0; i < obstacles.length; i++) {
        let index = Array.prototype.lastIndexOf.call(ans, obstacles[i]);
        ans[index] = i + 1;
        if (index === ans.length - 1) {
            ans.push(obstacles[i]);
        } else {
            ans[index] = obstacles[i];
        }
    }

    // Print the result
    return ans;
}

