fun longestObstacleCourse(obstacles: IntArray): IntArray {
    val ans = IntArray(obstacles.size) { 0 }

    // Use a dynamic programming approach to find the longest obstacle course
    for (i in obstacles.indices) {
        val index = ans.binarySearch(obstacles[i])
        ans[index] = i + 1
        if (index < 0) {
            ans[index * -2 - 1] = obstacles[i]
        } else {
            ans[index] = obstacles[i]
        }
    }

    // Print the result
    return ans
}

