fn longest_obstacle_course(obstacles: Vec<i32>) -> Vec<i32> {
    let mut ans = vec![0; obstacles.len()];
    let mut dp = vec![];

    for obstacle in obstacles {
        let index = dp.binary_search(&obstacle).unwrap_or_else(|x| x);
        ans[index] = index + 1;
        if index == dp.len() {
            dp.push(obstacle);
        } else {
            dp[index] = obstacle;
        }
    }

    return ans;
}

