int maxFrequency(std::vector<int>& nums, int k) {
    nums.sort();
    int max_freq = 1, n = nums.size(), total = 0, i = 0;

    for (int j = 0; j < n; ++j) {
        total += nums[j];
        while (total < nums[j] * (j - i + 1) - k) {
            total -= nums[i];
            i++;
        }
        max_freq = std::max(max_freq, j - i + 1);
    }
    return max_freq;
}

