int maxDistance(const std::vector<int>& nums1, const std::vector<int>& nums2) {
    int i = 0, j = 0, max_dist = 0;
    while (i < nums1.size() && j < nums2.size()) {
        if (i <= j && nums1[i] <= nums2[j]) {
            max_dist = std::max(max_dist, j - i);
            j++;
        } else {
            i++;
        }
    }
    return max_dist;
}

