import (
	"fmt"
	"sort"
)

func findMiddleIndex(nums []int) int {
	sort.Ints(nums) // Sort the array to make the middle index calculation easier
	total_sum := 0
	left_sum := 0

	for i, num := range nums {
		if left_sum == total_sum-left_sum-num {
			return i
		}
		left_sum += num
		total_sum += num
	}

	return -1
}

