#include <queue>
#include <vector>

std::vector<int> assignTasks(std::vector<int>& servers, std::vector<int>& tasks) {
    std::priority_queue<std::pair<int, int>> freeServers;
    std::priority_queue<std::pair<int, int>> busyServers;
    int n = servers.size();
    int m = tasks.size();
    std::vector<int> ans(m, 0);

    for (int i = 0; i < n; ++i) {
        freeServers.push({servers[i], i});
    }

    int currentTask = 0;
    while (currentTask < m) {
        while (!busyServers.empty() && busyServers.top().first <= currentTask) {
            int idx = busyServers.top().second;
            freeServers.push({servers[idx], idx});
            busyServers.pop();
        }

        while (!freeServers.empty() && currentTask < m) {
            int idx = freeServers.top().second;
            ans[currentTask] = idx;
            busyServers.push({currentTask + tasks[currentTask], idx});
            currentTask++;
            freeServers.pop();
        }

        if (freeServers.empty()) {
            currentTask = busyServers.top().first;
        }
    }

    return ans;
}
