from typing import List

def secondMinimum(n: int, edges: List[List[int]], time: int, change: int) -> int:
    graph = [[] for _ in range(n + 1)]
    for edge in edges:
        graph[edge[0]].append(edge[1])
        graph[edge[1]].append(edge[0])

    dist = [float('inf')] * (n + 1)
    dist[1] = 0
    dist2 = [float('inf')] * (n + 1)
    dist2[1] = 0

    q = [(0, 1)]
    while q:
        cur_dist, cur = q.pop(0)
        if cur_dist > dist[cur]:
            continue
        for next in graph[cur]:
            next_dist = cur_dist + time
            wait_time = (next_dist // change % 2 == 1) * change
            next_dist += wait_time
            if next_dist < dist[next]:
                dist[next] = next_dist
                q.append((next_dist, next))
            if next_dist < dist2[next]:
                dist2[next] = next_dist
                q.append((next_dist, next))

    return dist2[n]

