func secondMinimum(n int, edges [][]int, time int, change int) int {
	graph := make([][]int, n+1)
	for i := 0; i <= n; i++ {
		graph[i] = make([]int, 0)
	}
	for _, edge := range edges {
		graph[edge[0]].append(edge[1])
		graph[edge[1]].append(edge[0])
	}

	dist := make([]int, n+1)
	dist[1] = 0
	dist2 := make([]int, n+1)
	dist2[1] = 0

