	q = append(q, [2]int{0, 1})

	for len(q) > 0 {
		curDist, cur := q[0]
		q = q[1:]
		if curDist > dist[cur] {
			continue
		}
		for _, next := range graph[cur] {
			nextDist := curDist + time
			waitTime := (nextDist / change % 2 == 1) * change
			nextDist += waitTime
			if nextDist < dist[next] {
				dist[next] = nextDist
				q = append(q, [2]int{nextDist, next})
			}
			if nextDist < dist2[next] {
				dist2[next] = nextDist
				q = append(q, [2]int{nextDist, next})
			}
		}
	}

	return dist2[n]
}

