fn second_minimum(n: i32, edges: Vec<Vec<i32>>, time: i32, change: i32) -> i32 {
    let mut graph: HashMap<i32, Vec<i32>> = HashMap::new();
    for edge in &edges {
        graph.entry(*edge[0]).or_insert(Vec::new()).push(*edge[1]);
        graph.entry(*edge[1]).or_insert(Vec::new()).push(*edge[0]);
    }

    let mut dist: HashMap<i32, i32> = HashMap::new();
    dist.insert(1, 0);
    let mut dist2: HashMap<i32, i32> = HashMap::new();
    dist2.insert(1, 0);

    let mut q: Vec<(i32, i32)> = Vec::new();
    q.push((0, 1));

    while !q.is_empty() {
        let (cur_dist, cur) = q.pop().unwrap();
        if cur_dist > dist[&cur] {
            continue;
        }
        for next in &graph[&cur] {
            let next_dist = cur_dist + time;
            let wait_time = (next_dist / change % 2 == 1) * change;
            next_dist += wait_time;
            if next_dist < dist[&next] {
                dist.insert(*next, next_dist);
                q.push((next_dist, *next));
            }
            if next_dist < dist2[&next] {
                dist2.insert(*next, next_dist);
                q.push((next_dist, *next));
            }
        }
    }
    return dist2[&n];
}

