#include<vector>

int maxQuality_dfs(int node, int time_left, std::vector<int>& visited, std::vector<int>& values, std::vector<std::vector<int>>& neighbors) {
    int acc = 0;
    for (const auto& edge : neighbors[node]) {
        int neighbor = edge[0], cost = edge[1];
        if (time_left >= cost && visited[neighbor] == 0) {
            visited[neighbor] = 1;
            acc = std::max(acc, values[neighbor] + maxQuality_dfs(neighbor, time_left - cost, visited, values, neighbors));
            visited[neighbor] = 0;
        }
    }
    return acc;
}

int maxQuality(std::vector<int>& values, std::vector<std::vector<int>>& edges, int maxTime) {
    std::vector<std::vector<int>> neighbors(values.size());
    for (const auto& edge : edges) {
        neighbors[edge[0]].push_back({edge[1], edge[2]});
        neighbors[edge[1]].push_back({edge[0], edge[2]});
    }
    std::vector<int> visited(values.size(), 0);
    return maxQuality_dfs(0, maxTime, visited, values, neighbors);
}
