import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] values = {0, 32, 10, 43};
        int[][] edges = {{0, 1, 10}, {1, 2, 15}, {0, 3, 10}};
        int maxTime = 49;

        // Create a graph representation of the edges
        List<List<int[]>> neighbors = new ArrayList<>();
        for (int[] edge : edges) {
            neighbors.add(new ArrayList<>());
        }

        for (int i = 0; i < edges.length; i++) {
            int[] edge = edges[i];
            neighbors.get(edge[0]).add(new int[]{edge[1], edge[2]});
            neighbors.get(edge[1]).add(new int[]{edge[0], edge[2]});
        }

        // Initialize the visited array
        boolean[] visited = new boolean[values.length];

        // Function to calculate the maximum quality
        int maxQuality = maxQuality(values, neighbors, maxTime, visited);

        System.out.println("Maximum quality: " + maxQuality);
    }

    // Function to calculate the maximum quality
    private static int maxQuality(int[] values, List<List<int[]>> neighbors, int maxTime, boolean[] visited) {
        int maxQuality = 0;

        // Recursively calculate the maximum quality
        for (int i = 0; i < values.length; i++) {
            if (!visited[i]) {
                visited[i] = true;
                maxQuality = Math.max(maxQuality, values[i] + maxQuality(neighbors.get(i), maxTime - values[i], visited));
                visited[i] = false;
            }
        }

        return maxQuality;
    }
}
