#include <vector>
#include <algorithm>

int maxTasks(const std::vector<int>& tasks, const std::vector<int>& workers, int pills, int strength) {
  std::vector<int> sortedTasks = tasks;
  std::vector<int> sortedWorkers = workers;

  std::sort(sortedTasks.begin(), sortedTasks.end());
  std::sort(sortedWorkers.begin(), sortedWorkers.end());

  int cnt = 0;
  int i = 0;
  for (int j = 0; j < pills; ++j) {
    while (i < sortedTasks.size() && sortedTasks[i] > sortedWorkers[j] + strength) {
      ++i;
    }
    if (i < sortedTasks.size()) {
      ++cnt;
      ++i;
    }
  }

  i = 0;
  for (int j = pills; j < sortedWorkers.size(); ++j) {
    if (i < sortedTasks.size() && sortedTasks[i] <= sortedWorkers[j]) {
      ++cnt;
      ++i;
    }
  }

  return cnt;
}
