int timeToBuyTickets(const std::vector<int>& tickets, int k) {
    int time = 0;
    while (tickets[k] > 0) {
        for (int i = 0; i < tickets.size(); ++i) {
            if (tickets[i] > 0) {
                tickets[i] -= 1;
                time += 1;
                if (i == k && tickets[k] == 0) {
                    break;
                }
            }
        }
    }
    return time;
}

