public int largestEvenSum(int[] nums, int k) {
    // Sort the array of even numbers in descending order
    List<Integer> evens = Arrays.stream(nums).filter(num -> num % 2 == 0).sorted((a, b) -> b - a).collect(Collectors.toList());
    // Sort the array of odd numbers in descending order
    List<Integer> odds = Arrays.stream(nums).filter(num -> num % 2 != 0).sorted((a, b) -> b - a).collect(Collectors.toList());

    int sum = 0;
    for (int i = 0; i < k; i++) {
        if (!evens.isEmpty()) {
            sum += evens.remove();
        }
    }

    for (int i = 0; i < k - 1; i += 2) {
        if (!odds.isEmpty()) {
            int first = odds.remove();
            if (!odds.isEmpty()) {
                int second = odds.remove();
                sum += first + second;
            }
        }
    }

    return sum % 2 == 0 ? sum : -1;
}
