public int numberOfWeakCharacters(int[][] properties) {
    // Sort the properties by attack strength in descending order
    properties.sort((a, b) -> Integer.compare(b[0], a[0]));

    int maxDefense = 0;
    int weakCount = 0;
    for (int[] property : properties) {
        if (property[1] < maxDefense) {
            weakCount++;
        } else {
            maxDefense = property[1];
        }
    }

    return weakCount;
}
