bool canSortUsingSwap(std::vector<int>& nums) {
    for (int i = 1; i < nums.size(); i++) {
        if (nums[i] < nums[i - 1]) {
            int temp = nums[i];
            nums[i] = nums[i - 1];
            nums[i - 1] = temp;
            if (isSorted(nums)) {
                return true;
            }
            temp = nums[i];
            nums[i] = nums[i - 1];
            nums[i - 1] = temp;
        }
    }
    return false;
}

bool isSorted(std::vector<int>& nums) {
    for (int i = 1; i < nums.size(); i++) {
        if (nums[i] < nums[i - 1]) {
            return false;
        }
    }
    return true;
}

int main() {
    std::vector<int> bank = { "011001 ", "000000 ", "010100 ", "001000 " };
    std::cout << canSortUsingSwap(bank) << std::endl;
    return 0;
}
