#include <algorithm>

int max_computer_runtime(int n, int* batteries) {
    std::sort(batteries, batteries + batteries.length);
    int result = 0;
    for (int i = 0; i < batteries.length; i++) {
        result = std::max(result, std::min(n, batteries.length - i) * batteries[i]);
    }
    return result;
}

int main() {
    int n = 2;
    int batteries[] = {3, 3, 3};
    std::cout << max_computer_runtime(n, batteries) << std::endl;
    return 0;
}
