int maxFruits(std::vector<std::pair<int, int>> fruits, int startPos, int k) {
    int n = fruits.size();
    int left[n + 1], right[n + 1];
    int j = 0;

    for (int i = 0; i < n; ++i) {
        while (j < n && fruits[j][0] - fruits[i][0] <= k) {
            right[i + 1] += fruits[j][1];
            ++j;
        }
        right[i + 1] += right[i];
        if (j < n && fruits[j][0] - startPos <= k) {
            right[0] += fruits[j][1];
            ++j;
        }
    }

