        Map<Integer, List<Integer>> indices = new HashMap<>();
        List<Integer> intervals = new ArrayList<>(arr.size());

        for (int i = 0; i < arr.size(); ++i) {
            indices.put(arr.get(i), new ArrayList<>());
            indices.get(arr.get(i)).add(i);
        }

        for (int i = 0; i < arr.size(); ++i) {
            for (int j : indices.get(arr.get(i))) {
                intervals.add(i, Math.abs(j - i));
            }
        }

        return Collections.max(intervals);
    }
}
