public int maxScore(int[] scores, int[][] edges) {
    // Create an adjacency list to store the neighbors of each node
    List<List<Integer>> adjList = new ArrayList<>(scores.length);
    for (int i = 0; i < scores.length; i++) {
        adjList.add(new ArrayList<>());
    }

    // Create a result variable to store the maximum score
    int result = -1;

    // Iterate over the edges and add their neighbors to the adjacency list
    for (int[] edge : edges) {
        adjList.get(edge[0]).add(edge[1]);
        adjList.get(edge[1]).add(edge[0]);
    }

    // Iterate over the nodes and calculate the maximum score
    for (int i = 0; i < scores.length; i++) {
        for (int neighbor : adjList.get(i)) {
            for (int next : adjList.get(neighbor)) {
                if (next != i && next != neighbor) {
                    result = Math.max(result, scores[i] + scores[neighbor] + scores[next]);
                }
            }
        }
    }

    return result;
}
