std::vector<int> rearrangeArrayAroundPivot(const std::vector<int>& nums, int pivot) {
    std::vector<int> result(nums.size());
    int count = 0;
    for (int num : nums) {
        if (num >= pivot) {
            result[count++] = num;
        } else {
            result[count++] = pivot;
        }
    }
    result[count] = pivot;
    return result;
}
