public int[] lonelyNumbers(int[] nums) {
    Set<Integer> numSet = new HashSet<>(nums);
    int[] lonely = new int[nums.length];
    for (int i = 0; i < nums.length; i++) {
        if (!numSet.contains(nums[i] - 1) && !numSet.contains(nums[i] + 1)) {
            lonely[i] = nums[i];
        }
    }
    return lonely;
}
