// Function to evaluate a binary tree
bool evalTree(TreeNode* root) {
    // Base case: leaf node
    if (!root->left && !root->right) {
        return root->val == 1;
    }

    // Recursively evaluate left and right subtrees
    bool left = evalTree(root->left);
    bool right = evalTree(root->right);

    // Check if the current node is a 2-node
    if (root->val == 2) {
        return left || right;
    }

    // Return the result of both subtrees
    return left && right;
}

