int findSubarrayLength(vector<int>& nums, int threshold) {
    int n = nums.size();
    int left = 0, right = 0, sum = 0;
    int maxLength = -1;

    while (right < n) {
        sum += nums[right];
        while (sum * (right - left + 1) < threshold * (right - left + 1)) {
