int shortest_unrollable_sequence(const std::vector<int>& rolls, int k) {
    std::vector<int> count(k + 1, 0);
    for (int roll : rolls) {
        count[roll] += 1;
    }

    int len = 1;
    while (true) {
        int max_subsequences = 1;
        for (int i = 1; i <= k; ++i) {
            max_subsequences *= count[i] + (1 if len == 1 else 0);
        }

        if (max_subsequences < len * rolls.size()) {
            return len;
        }

        len++;
    }
}

