import java.util.*;

public class Solution {
    public int shortestUnrollableSequence(int[] rolls, int k) {
        // Initialize a count array to store the number of occurrences of each roll
        int[] count = new int[k + 1];
        for (int roll : rolls) {
            count[roll] += 1;
        }

        // Initialize the length of the unrollable sequence to 1
        int len = 1;
        while (true) {
            // Calculate the maximum number of subsequences that can be formed
            int maxSubsequences = 1;
            for (int i = 1; i <= k; i++) {
                maxSubsequences *= count[i] + (1 if len == 1 else 0);
            }

            // Check if the maximum number of subsequences is less than the current length
            if (maxSubsequences < len * rolls.length) {
                return len;
            }

            // Increment the length of the unrollable sequence
            len++;
        }
    }

    public static void main(String[] args) {
        int[] rolls = {4, 2, 1, 2, 3, 3, 2, 4, 1};
        int k = 4;
        System.out.println(new Solution().shortestUnrollableSequence(rolls, k));
    }
}
