import java.util.*;
import java.util.stream.Collectors;

public class Solution {
    public int countExcellentPairs(int[] nums, int k) {
        Map<Integer, Integer> frequency = new HashMap<>();
        for (int num : nums) {
            frequency.put(num, frequency.getOrDefault(num, 0) + 1);
        }

        int count = 0;
        for (Map.Entry<Integer, Integer> entry1 : frequency.entrySet()) {
            for (Map.Entry<Integer, Integer> entry2 : frequency.entrySet()) {
                if ((entry1.getKey() | entry2.getKey()) == (entry1.getKey() & entry2.getKey()) && (entry1.getKey() | entry2.getKey()) >= k) {
                    count += (entry1.getKey() == entry2.getKey()) ? entry1.getValue() * (entry1.getValue() - 1) / 2 : entry1.getValue() * entry2.getValue();
                }
            }
        }

        return count;
    }
}
