public int minOperations(String blocks, int k) {
    int n = blocks.length();
    int res = k;
    int w = 0;
    int b = 0;
    int i = 0;
    int j = 0;

    while (j < n) {
        if (blocks.charAt(j) == 'W') {
            w++;
        }
        while (b > k || (b == k && blocks.charAt(i) == 'B')) {
            if (blocks.charAt(i) == 'W') {
                w--;
                i++;
            } else {
                b--;
                i++;
            }
        }
        if (b == k) {
            res = Math.min(res, w);
        } else {
            b++;
        }
        j++;
    }

    return res;
}
