import java.util.*;

public class Solution {
    public String shiftCharacters(String s, List<List<Integer>> shifts) {
        // Initialize a vector to store the shift values
        int[] shiftValues = new int[s.length()];
        for (List<Integer> shift : shifts) {
            int start = shift.get(0), end = shift.get(1), direction = shift.get(2);
            int value = (direction == 1) ? 1 : -1;
            shiftValues[start] += value;
            if (end + 1 < s.length()) shiftValues[end + 1] -= value;
        }

        // Calculate the cumulative sum of shift values
        for (int i = 1; i < s.length(); i++) {
            shiftValues[i] += shiftValues[i - 1];
        }

        // Apply the shift to each character
        for (int i = 0; i < s.length(); i++) {
            s = s.substring(0, i) + (char) ((s.charAt(i) - 'a' + shiftValues[i]) % 26 + 'a') + s.substring(i + 1);
        }

        return s;
    }
}
