CREATE FUNCTION min_days(power INT[]) RETURNS INT
LANGUAGE sql
IMMUTABLE
AS $$
DECLARE
    n INT := ARRAY_LENGTH(power);
    ans INT := 1e9;
    dp INT[];
    sorted_power INT[];
BEGIN
    SELECT * INTO sorted_power FROM power ORDER BY power;
    dp := ARRAY[0];
    FOR i IN 0 .. (1 << n) LOOP
        power_sum := 0;
        FOR j IN 0 .. n LOOP
            IF i AND (1 << j) THEN
                power_sum := power_sum + sorted_power[j];
            END IF;
        END LOOP;
        gain := 1 + BIT_LENGTH(i);
        FOR j IN 0 .. n LOOP
            IF NOT (i AND (1 << j)) AND gain > power[j] THEN
                dp[i || (1 << j)] := MIN(dp[i || (1 << j)], dp[i] + 1);
            END IF;
        END LOOP;
    END LOOP;
    RETURN dp[(1 << n) - 1];
END;
$$;
