package main

import (
	"fmt"
	"sort"
)

func minDays(power []int) int {
	n := len(power)
	ans := 1e9
	dp := make([]int, 1<<n)
	dp[0] = 0

	// Sort the power array in ascending order
	sort.Ints(power)

	for i := 0; i < 1<<n; i++ {
		powerSum := 0
		for j := 0; j < n; j++ {
			if i&(1<<j) != 0 {
				powerSum += power[j]
			}
		}
		gain := 1 + binary.LittleEndian.Uint64(fmt.Sprintf("%016b", i))&((1<<n)-1)
		for j := 0; j < n; j++ {
			if !(i&(1<<j)) && gain > power[j] {
				dp[i|(1<<j)] = min(dp[i|(1<<j)], dp[i]+1)
			}
		}
	}
	return dp[(1<<n)-1]
}

