#include <algorithm>

int max_matchings(const std::vector<int>& players, const std::vector<int>& trainers) {
    std::sort(players.begin(), players.end());
    std::sort(trainers.begin(), trainers.end());

    int player_index = 0, trainer_index = 0, match_count = 0;
    while (player_index < players.size() && trainer_index < trainers.size()) {
        if (players[player_index] <= trainers[trainer_index]) {
            match_count++;
            player_index++;
            trainer_index++;
        } else {
            trainer_index++;
        }
    }

    return match_count;
}

int main() {
    std::vector<int> players = {4, 7, 9};
    std::vector<int> trainers = {8, 2, 5, 8};

    std::cout << max_matchings(players, trainers) << std::endl;

    return 0;
}
