import java.util.HashMap;
import java.util.Map;

public class PrefixScoreSum {
    public static int[] prefixScoreSum(String[] words) {
        Map<String, Integer> prefixCount = new HashMap<>();

        for (String word : words) {
            String prefix = "";
            for (char c : word.toCharArray()) {
                prefix += c;
                prefixCount.put(prefix, prefixCount.getOrDefault(prefix, 0) + 1);
            }
        }

        int[] result = new int[words.length];
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            int score = 0;
            for (char c : word.toCharArray()) {
                String prefix = "";
                for (char d : word.toCharArray()) {
                    prefix += d;
                    score += prefixCount.getOrDefault(prefix, 0);
                }
            }
            result[i] = score;
        }
        return result;
    }
}
```


