    if (vals[node] >= cur_max) {
        if (vals[node] > cur_max) {
            count++;
            cur_max = vals[node];
        }
        for (const auto& next : adj[node]) {
            if (next != parent) {
                dfs(next, node, adj, vals, cur_max, count);
            }
        }
    }
}
