public boolean canEqualFrequency(String word) {
    Map<Character, Integer> freq = new HashMap<>();
    for (char c : word.toCharArray()) {
        freq.put(c, freq.getOrDefault(c, 0) + 1);
    }

    Map<Integer, Integer> countFreq = new HashMap<>();
    for (int f : freq.values()) {
        countFreq.put(f, countFreq.getOrDefault(f, 0) + 1);
    }

    if (countFreq.size() != 2) {
        return false;
    }

    int a = countFreq.get(freq.entrySet().iterator().next().getValue());
    int b = countFreq.get(freq.entrySet().iterator().next().getValue());

    return (a == 1 && (a - 1 == b || a == 1)) || (b == 1 && (b - 1 == a || b == 1));
}
