public int flipTrees(int n, int[] queries) {
    Map<Integer, Boolean> flippedNodes = new HashMap<>();
    for (int query : queries) {
        flippedNodes.put(query, !flippedNodes.getOrDefault(query, false));
        while (query > 1) {
            query /= 2;
            flippedNodes.put(query, !flippedNodes.getOrDefault(query, false));
        }
    }

    int count = 0;
    for (boolean value : flippedNodes.values()) {
        if (value) {
            count++;
        }
    }

    return count;
}
```
