#include <vector>
#include <algorithm>

int min_total_distance(const std::vector<int>& robot, const std::vector<std::vector<int>>& factory) {
    std::sort(robot.begin(), robot.end());
    std::sort(factory.begin(), factory.end());

    int res = 0;
    int idx = 0;
    for (const auto& f_pos : factory) {
        while (f_pos[1] > 0 && idx < robot.size()) {
            res += std::abs(f_pos[0] - robot[idx]);
            idx++;
            f_pos[1]--;
        }
    }

    return res;
}
