def min_total_distance(robot: List[int], factory: List[List[int]]) -> int:
    robot.sort()
    factory.sort()

    res = 0
    idx = 0
    for f_pos, f_limit in factory:
        while f_limit > 0 and idx < len(robot):
            res += abs(f_pos - robot[idx])
            idx += 1
            f_limit -= 1

    return res
