int distinctAverages(int* nums, int n) {
    std::set<double> averages;
    std::sort(nums, nums + n);
    for (int i = 0; i < n / 2; ++i) {
        averages.insert((nums[i] + nums[n - 1 - i]) / 2.0);
    }
    return averages.size();
}

