public int countLcmSubarrays(int[] nums, int k) {
    int count = 0;
    for (int i = 0; i < nums.length; i++) {
        int currLcm = nums[i];
        for (int j = i; j < nums.length; j++) {
            currLcm = lcm(currLcm, nums[j]);
            if (currLcm == k) {
                count++;
            }
        }
    }
    return count;
}

