#include<vector>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

std::vector<std::vector<int>> findMinMax(TreeNode* root, std::vector<int>& queries) {
    if (!root) {
        return {};
    }

    std::vector<std::vector<int>> ans(queries.size(), std::vector<int>{-1, -1});
    for (size_t i = 0; i < queries.size(); i++) {
        TreeNode* node = root;
        int query = queries[i];
        while (node) {
            if (node->val < query) {
                ans[i][0] = node->val;
                node = node->right;
            } else {
                ans[i][1] = node->val;
                if (node->val == query) {
                    ans[i][0] = query;
                    break;
                }
                node = node->left;
            }
        }
    }
    return ans;
}
