#include <iostream>

// Define a struct to represent a node in the linked list
struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x) : val(x), next(nullptr) {}
};

// Function to remove nodes from the linked list
ListNode* removeNodes(ListNode* head) {
    if (!head) return nullptr;

    ListNode* maxNode = head;
    ListNode* currentNode = head;
    ListNode* prevNode = nullptr;

    while (currentNode && currentNode->next) {
        if (currentNode->next->val > maxNode->val) {
            if (prevNode) prevNode->next = currentNode->next;
            else head = currentNode->next;
            maxNode = currentNode->next;
        } else {
            prevNode = currentNode;
        }
        currentNode = currentNode->next;
    }

    maxNode->next = removeNodes(maxNode->next);
    return head;
}

int main() {
    ListNode* head = new ListNode(5);
    head->next = new ListNode(2);
    head->next->next = new ListNode(13);
    head->next->next->next = new ListNode(3);
    head->next->next->next->next = new ListNode(8);

    head = removeNodes(head);

    while (head) {
        std::cout << head->val << " ";
        head = head->next;
    }

    return 0;
}
