#include <iostream>
#include <vector>
#include <queue>
#include <unordered_map>

int minimumScore(int n, std::vector<std::vector<int>> roads) {
    std::unordered_map<int, std::vector<std::pair<int, int>>> adj;
    for (const auto& road : roads) {
        adj[road[0]].emplace_back(road[1], road[2]);
        adj[road[1]].emplace_back(road[0], road[2]);
    }

    int INF = 1e9;
    std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::function<bool(const std::pair<int, int>&, const std::pair<int, int>&)>> pq;
    pq.push({0, 1});

    std::vector<int> minDist(n + 1, INF);
    while (!pq.empty()) {
        int curDist = pq.top().first;
        pq.pop();
        if (curDist == minDist[n]) {
            return curDist;
        }
        if (curDist < minDist[curDist]) {
            minDist[curDist] = curDist;
            for (const auto& next : adj[curDist]) {
                int nextCity = next.first;
                int nextDist = next.second;
                int candidate_dist = std::max(curDist, nextDist);
                if (candidate_dist < minDist[nextCity]) {
                    pq.push({candidate_dist, nextCity});
                }
            }
        }
    }
    return -1;
}

