package main

import (
	"fmt"
	"sort"
)

func maxStarSum(vals []int, edges [][]int, k int) int {
	adj := make([][]int, len(vals))
	for _, edge := range edges {
		adj[edge[0]] = append(adj[edge[0]], vals[edge[1]])
		adj[edge[1]] = append(adj[edge[1]], vals[edge[0]])
	}

	var ans int
	for i := range vals {
		sort.Slice(adj[i], func(i, j int) bool { return adj[i][j] > adj[i][j-1] })
		sum := vals[i]
		for j := 0; j < k && j < len(adj[i]); j++ {
			sum += adj[i][j]
		}
		ans = max(ans, sum)
	}

	return ans
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func main() {
	vals := []int{1, 2, 3, 4, 10, -10, -20}
	edges := [][]int{{0, 1}, {1, 2}, {1, 3}, {3, 4}, {3, 5}, {3, 6}}
	k := 2
	fmt.Println(maxStarSum(vals, edges, k))
}
