use std::collections::HashMap;
use std::collections::HashSet;

fn max_star_sum(vals: &Vec<i32>, edges: &Vec<Vec<i32>>, k: i32) -> i32 {
    let mut adj: HashMap<i32, Vec<i32>> = HashMap::new();
    for edge in edges {
        adj.entry(edge[0]).or_insert(Vec::new()).push(edge[1]);
        adj.entry(edge[1]).or_insert(Vec::new()).push(edge[0]);
    }

    let mut ans = i32::MIN;
    for i in 0..vals.len() {
        let mut sum = vals[i] as i32;
        for _ in 0..k {
            if let Some(&val) = adj.get(&i) {
                sum += val[0] as i32;
            }
        }
        ans = std::cmp::max(ans, sum);
    }

    ans
}

fn main() {
    let vals = vec![1, 2, 3, 4, 10, -10, -20];
    let edges = vec![vec![0, 1], vec![1, 2], vec![1, 3], vec![3, 4], vec![3, 5], vec![3, 6]];
    let k = 2;
    println!("{}", max_star_sum(&vals, &edges, k));
}
