package main

import (
	"fmt"
	"sort"
)

func maxPoints(grid [][]int, queries []int) []int {
	m := len(grid)
	n := len(grid[0])
	dx := []int{-1, 0, 1, 0}
	dy := []int{0, 1, 0, -1}
	result := make([]int, len(queries))

	for i, query := range queries {
		points := 0
		visited := make(map[string]bool)
		stack := make([]int, 0, 4)
		stack = append(stack, 0, 0)

		for len(stack) > 0 {
			x, y := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			coordStr := fmt.Sprintf("%d,%d", x, y)

			if !visited[coordStr] && grid[x][y] < query {
				visited[coordStr] = true
				points++
				for _, i := range []int{0, 1, 2, 3} {
					nx := x + dx[i]
					ny := y + dy[i]
					if nx >= 0 && nx < m && ny >= 0 && ny < n {
						stack = append(stack, nx, ny)
					}
				}
			}
		}
		result[i] = points
	}
	return result
}

func main() {
	grid := [][]int{{1, 2, 3}, {2, 5, 7}, {3, 5, 1}}
	queries := []int{5, 6, 2}
	fmt.Println(maxPoints(grid, queries))
}
