int length_of_cycle(int n, std::vector<std::pair<int, int>> queries) {
    std::vector<int> result;
    for (const auto& query : queries) {
        int A = query.first, B = query.second;
        int depth_A = 0, depth_B = 0;
        while (A != B) {
            if (A < B) {
                A = B;
            }
            A >>= 1;
            depth_A++;
        }
        result.push_back(depth_A + depth_B);
    }
    return result;
}

int main() {
    int n = 3;
    std::vector<std::pair<int, int>> queries = {{5, 3}, {4, 7}, {2, 3}};
    std::vector<int> expected_result = {4, 5, 3};
    std::vector<int> actual_result = length_of_cycle(n, queries);
    if (actual_result == expected_result) {
        std::cout << "Test passed!" << std::endl;
    } else {
        std::cout << "Test failed!" << std::endl;
    }
    return 0;
}
