import java.util.*;
import java.util.PriorityQueue;

public class Solution {
    public int getLastMoment(int n, int k, List<List<Integer>> time) {
        // Create a priority queue for each side of the graph
        PriorityQueue<int[]> left = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
        PriorityQueue<int[]> right = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));

        // Add the first k moments to the left side
        for (int i = 0; i < k; i++) {
            left.add(new int[]{time.get(i)[0] + time.get(i)[2], i});
        }

        // Simulate the graph
        while (n > 0) {
            // Pop the right side until the top of the left side is greater than or equal to the top of the right side
            while (!right.isEmpty() && right.peek()[0] <= left.peek()[0]) {
