            // Pop the top of the left side
            int[] leftTop = left.poll();
            // Update the time of the left side
            time.get(leftTop[1])[2] += time.get(leftTop[1])[3] + time.get(leftTop[1])[0] + time.get(leftTop[1])[1];
            // Add the updated time to the right side
            right.add(new int[]{leftTop[0] + time.get(leftTop[1])[1], leftTop[1]});
            n--;
        }

        // Get the last moment from the right side
        int lastMoment = -1;
        while (!right.isEmpty()) {
            lastMoment = Math.max(lastMoment, time.get(right.poll()[1])[2]);
        }
        return lastMoment;
    }
}
