import java.util.*;
import java.util.stream.Collectors;

public class Solution {
    public int getMaxCost(int n, List<List<Integer>> edges, int[] price) {
        // Create adjacency list and price array
        List<List<Integer>> adj = new ArrayList<>();
        int[] priceArray = Arrays.stream(price).boxed().toArray(Integer[]::new);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (List<Integer> edge : edges) {
            adj.get(edge.get(0)).add(edge.get(1));
            adj.get(edge.get(1)).add(edge.get(0));
        }

        // Initialize DP array
        int[][] dp = new int[n][2];
        for (int i = 0; i < n; i++) {
            dp[i][0] = priceArray[i];
            dp[i][1] = 0;
        }

        // Perform DFS
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                for (int k : adj.get(j)) {
                    if (k == i) continue;
                    dp[i][0] = Math.max(dp[i][0], dp[k][0] + priceArray[i] - dp[k][1]);
                    dp[i][1] = Math.max(dp[i][1], dp[k][1]);
                }
            }
        }

        // Find maximum cost
        int maxCost = 0;
        for (int i = 0; i < n; i++) {
            maxCost = Math.max(maxCost, dp[i][0] - dp[i][1]);
        }

        return maxCost;
    }
}
