#include <vector>

std::vector<int> separateDigits(const std::vector<int>& nums) {
    std::vector<int> answer;
    for(auto num : nums) {
        std::vector<int> digits;
        while(num) {
            digits.insert(digits.begin(), num % 10);
            num /= 10;
        }
        answer.insert(answer.end(), digits.begin(), digits.end());
    }
    return answer;
}
