public class Solution {
    public int minCostToEqualBaskets(int[] basket1, int[] basket2) {
        // Create a dictionary to store the difference counts
        Map<Integer, Integer> diffCount = new HashMap<>();
        for (int i = 0; i < basket1.length; i++) {
            int diff = basket1[i] - basket2[i];
            diffCount.put(diff, diffCount.getOrDefault(diff, 0) + 1);
        }

        // Initialize the minimum cost and sum
        int minCost = Integer.MAX_VALUE;
        int sum = 0;

        // Iterate over the difference counts
        for (Map.Entry<Integer, Integer> entry : diffCount.entrySet()) {
            // If the count is equal to the negative count, calculate the cost
            if (entry.getValue() == diffCount.getOrDefault(-entry.getKey(), 0)) {
                int cost = 0;
                for (int i = 0; i < basket1.length; i++) {
                    if (basket1[i] - basket2[i] == entry.getKey()) {
                        cost += Math.min(basket1[i], basket2[i]);
                    }
                }
                minCost = Math.min(minCost, cost);
            }
        }

        // Return the minimum cost divided by 2 if it is not infinity
        return -1 if (minCost == Integer.MAX_VALUE) else minCost / 2;
    }
}
