import java.util.*;
import java.math.*;

public class Solution {
    public int countSquareFreeSubsets(int[] nums) {
        // Use a HashMap to store the frequency of each number
        Map<Integer, Integer> freqMap = new HashMap<>();
        for (int num : nums) {
            freqMap.put(num, freqMap.getOrDefault(num, 0) + 1);
        }

        // Initialize the dynamic programming table
        int[][] dp = new int[61][1001];
        dp[0][0] = 1;

        // Calculate the number of subsets for each frequency
        for (int freq = 1; freq <= 61; freq++) {
            for (int ns = 0; ns <= 1000; ns++) {
                dp[freq][ns] = (dp[freq - 1][ns] + dp[freq - 1][ns + freq]) % 1000000007;
            }
        }

        // Calculate the number of square-free subsets
        for (int num : freqMap.keySet()) {
            int freq = freqMap.get(num);
            for (int ns = 0; ns <= 1000; ns++) {
                dp[freq][ns] = (dp[freq][ns] - dp[freq - 1][ns] * (freq - 1) % 1000000007 + 1000000007) % 1000000007;
            }
        }

        return dp[61][0];
    }
}
