import java.util.*;

public class Solution {
    public int totalWaysToSplitRanges(int[][] ranges) {
        // Sort the ranges by their end points
        Arrays.sort(ranges, (a, b) -> a[1] - b[1]);

        // Initialize variables to keep track of overlapping and non-overlapping ranges
        int overlapping = 0, non_overlapping = 1, prev_end = -1;

        // Iterate through the ranges
        for (int[] range : ranges) {
            // If the current range overlaps with the previous range, increment overlapping
            if (range[0] <= prev_end) {
                overlapping++;
            } else {
                // Otherwise, increment non-overlapping
                non_overlapping++;
            }
            // Update the end point of the previous range
            prev_end = Math.max(prev_end, range[1]);
        }

        // Calculate the result
        long result = 1;
        for (int i = 1; i <= overlapping; ++i) {
            result = (result * 2) % 1000000007;
        }
        return (int) result;
    }
}
