#include <vector>
#include <algorithm>

int countBeautifulSubsets(std::vector<int>& nums, int k) {
    nums.sort();
    int ans = 0;
    std::vector<int> dp(nums.size(), 1);
    for (int i = 0; i < nums.size(); ++i) {
        int l = r = 0;
        for (int j = i; j >= 0; --j) {
            while (l < j && nums[j] - nums[l] >= k) {
                ++l;
            }
            while (r + 1 < j && nums[r + 1] - nums[j] < k) {
                ++r;
            }
            dp[j] -= dp[l - 1] if (l <= r) else 0;
            dp[j] += dp[j - 1] + 1;
            ans += dp[j];
        }
    }
    return ans;
}
