#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> nums = {3, 1, 6, 8};
    std::vector<int> queries = {1, 5};

    std::vector<int> answer;
    for (int query : queries) {
        int operations = 0;
        for (int num : nums) {
            operations += std::abs(num - query);
        }
        answer.push_back(operations);
