#include <iostream>
#include <vector>
#include <queue>

int shortestCycleLength(int n, int** edges) {
    std::vector<std::vector<int>> graph(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            graph[i].push_back(j);
        }
    }

    int shortestCycle = n + 1;
    for (int start = 0; start < n; ++start) {
        int* dist = new int[n];
        for (int i = 0; i < n; ++i) {
            dist[i] = n + 1;
        }
        dist[start] = 0;
        std::priority_queue<std::pair<int, int>> queue;
        queue.push({0, start});

        while (!queue.empty()) {
            int cur = queue.top().second;
            queue.pop();
            for (int neigh : graph[cur]) {
                if (dist[neigh] == n + 1) {
                    dist[neigh] = dist[cur] + 1;
                    queue.push({dist[neigh], neigh});
                } else if (dist[neigh] >= dist[cur] - 1) {
                    shortestCycle = std::min(shortestCycle, dist[cur] + dist[neigh] + 1);
                }
            }
        }
        delete[] dist;
    }

    return shortestCycle == n + 1 ? -1 : shortestCycle;
}

