import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int[] ais = new int[n];
        for (int i = 0; i < n; i++) {
            ais[i] = Integer.parseInt(br.readLine());
        }
        int q = Integer.parseInt(br.readLine());
        Map<Integer, Integer> pares = new HashMap<>();
        for (int a : ais) {
            for (int i = 1; i <= k; i++) {
                int p = (i + 1) * a;
                if (!pares.containsKey(p) || i + 1 < pares.get(p)) {
                    pares.put(p, i + 1);
                }
            }
        }
        int m = 1000000000;
        for (int i = 0; i < q; i++) {
            int x = Integer.parseInt(br.readLine());
            int ans = 1000;
            int minimo = m;
            for (Map.Entry<Integer, Integer> entry : pares.entrySet()) {
                int plata = entry.getKey();
                int deuda = entry.getValue();
                if (plata == x) {
                    if (deuda <= k) {
                        if (deuda < minimo) {
                            minimo = deuda;
                        }
                    }
                } else {
                    int r = x - plata;
                    if (r > 0 && pares.containsKey(r)) {
                        int deuda2 = pares.get(r);
                        if (deuda + deuda2 < minimo) {
                            if (deuda + deuda2 <= k) {
                                minimo = deuda + deuda2;
                            }
                        }
                    }
                }
            }
            if (minimo == m) {
                System.out.println(-1);
            } else {
                System.out.println(minimo);
            }
        }
    }
}
