            if s[i] == s[j] && i != j {
                is_palindrome = false;
                break;
            }
        }
        if !is_palindrome {
            n += 1;
            s = n.to_string();
            i = 0;
        }
    }
    writeln!(stdout(), "{}", s).unwrap();
    Ok(())
}
