            int b = Integer.parseInt(st.nextToken());
            a = P[a];
            b = P[b];
            if (a > b) {
                a = P[b];
                b = P[a];
            }
            v.get(b).add(a);
        }
        int mm = -1;
        long ans = 0;
        for (int i = 1; i <= n; i++) {
            for (int j = 0; j < v.get(i).size(); j++) {
                mm = Math.max(mm, v.get(i).get(j));
            }
            ans += mm + 1;
        }
        System.out.println((n * (n + 1)) / 2 - ans);
    }
}
