import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int h = sc.nextInt();
        int w = sc.nextInt();
        int y = sc.nextInt();
        int x = sc.nextInt();
        String ins = sc.next();
        int n = ins.length();
        boolean[][] vis = new boolean[w][h];
        int[] dx = {0, 0, -1, 1};
        int[] dy = {-1, 1, 0, 0};
        int[] ret = new int[n];
        int i = 0;
        while (i < n) {
            int nx = x;
            int ny = y;
            for (int k = 0; k < 4; k++) {
                nx += dx[k];
                ny += dy[k];
                if (nx < 0 || nx >= w || ny < 0 || ny >= h || vis[nx][ny]) break;
            }
