int find_path(int x, int y) {
    std::vector<int> p1;
    std::vector<int> p2;

    while (x != 0) {
        p1.push_back(x);
        x = x / 2;
    }

    while (y != 0) {
        p2.push_back(y);
        y = y / 2;
    }

    p1.reverse();
    p2.reverse();

    int ind = 0;
    for (int i = 0; i < std::min(p1.size(), p2.size()); ++i) {
        if (p1[i] == p2[i]) {
            ind = i;
        } else {
            break;
        }
    }

    std::vector<int> path;
    for (int i = ind; i < p1.size(); ++i) {
        path.push_back(p1[i]);
    }
    path.reverse();
    for (int i = ind + 1; i < p2.size(); ++i) {
        path.push_back(p2[i]);
    }

    return path;
}

int main() {
    int q;
    std::cin >> q;
    std::unordered_map<std::pair<int, int>, int> cost;
    for (int i = 0; i < q; ++i) {
        int a;
        std::cin >> a;
        std::vector<int> b = find_path(a, a);
        if (a == 1) {
            int w;
            std::cin >> w;
            for (int j = 1; j < b.size(); ++j) {
                if (!(b[j] < b[j - 1])) {
                    cost[{b[j], b[j - 1]}] = w;
                    cost[{b[j - 1], b[j]}] = w;
                } else {
                    cost[{b[j], b[j - 1]}] += w;
                    cost[{b[j - 1], b[j]}] += w;
                }
            }
        } else {
            int ans = 0;
            for (int j = 1; j < b.size(); ++j) {
                if (b[j] < b[j - 1]) {
                    if (b[j] in cost) {
                        ans += cost[b[j]];
                    }
                }
            }
            std::cout << ans << std::endl;
        }
    }
    return 0;
}
