#include <iostream>
#include <cmath>

double time_distance(double v0, double a, double d) {
  //quadratic equation. Time is positive ==> root with (+discriminant) in quadratic formula
  //d = v0*t + (a/2)*t^2
  return (-v0 + (v0*v0 + 2*a*d).sqrt()) / a;
}

double time_accelerating(double v0, double v1, double a) {
  return (v1 - v0) / a;
}

double time_speed(double v, double d) {
  return d / v;
}

double distance_travelled(double v0, double t, double a) {
  return v0*t + (a/2)*t*t;
}

int main() {
  int a, v;
  std::cin >> a >> v;
  int l, d, w;
  std::cin >> l >> d >> w;

  double time = 0;

  double time_to_d = time_distance(0, a, d);
  double time_to_v = time_accelerating(0, v, a);

  if (v < w) {
    //Accelerating 0-v
    double acceleration_time = time_to_v;
    double acceleration_distance = distance_travelled(0, acceleration_time, a);

    if (acceleration_distance >= l) {
      //Accelerating 0-?
      time = time_distance(0, a, l);
    } else {
      //Accelerating 0-v
      time = acceleration_time;
      //Max speed v
      time += time_speed(v, l - acceleration_distance);
    }
  } else {
    if (time_to_v <= time_to_d) {
      //Accelerating 0-v
      double acceleration_time = time_to_v;
      double acceleration_distance = distance_travelled(0, acceleration_time, a);

      //Decelerating v-w
      double deceleration_time = time_accelerating(v, w, -a);
      double deceleration_distance = distance_travelled(v, deceleration_time, -a);
    } else {
      //Accelerating 0-w
      double acceleration_time = time_accelerating(0, w, a);
      double acceleration_distance = distance_travelled(0, acceleration_time, a);

      double remaining_distance = d - acceleration_distance;
      //Remaining distance --> Acceleration = -Deceleration ==> half remaining distance each action 
      double delta_time = time_distance(w, a, remaining_distance/2);
      //Accelerating 0-? and Decelerating ?-w
      time = acceleration_time + 2*delta_time;
    }
  }

  //Accelerating w-v
  double acceleration_time = time_accelerating(w, v, a);
  double acceleration_distance = distance_travelled(w, acceleration_time, a);
  if (acceleration_distance >= l - d) {
    //Accelerating w-?
    time += time_distance(w, a, l - d);
  } else {
    //Accelerating w-v
    time += acceleration_time;
    //Max speed v
    time += time_speed(v, l - (d + acceleration_distance));
  }

  std::cout << time << std::endl;

  return 0;
}
