int main() {
    int n, h;
    std::cin >> n >> h;
    std::vector<int> l(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> l[i];
    }
    std::vector<int> k(n);
    int r = 0;
    for (int i = 0; i < n; ++i) {
        k[i] = l[i];
        std::sort(k.begin(), k.begin() + i + 1, std::greater<int>());
        int ans = 0;
        for (int j = 0; j < i + 1; j += 2) {
            ans += k[j];
        }
        if (ans <= h) {
            r = i + 1;
        } else {
            break;
        }
    }
    std::cout << r << std::endl;
    return 0;
}
