use std::io::{self, Write};
use std::num::ParseIntError;

fn main() -> io::Result<()> {
    let mut n = String::new();
    io::stdin().read_line(&mut n).unwrap();
    let n: usize = match n.trim().parse() {
        Ok(num) => num,
        Err(_) => return Err(io::Error::new(io::ErrorKind::InvalidInput, "Invalid input"))};

    let mut a = vec![0; n];
    for i in 0..n {
        let mut line = String::new();
        io::stdin().read_line(&mut line).unwrap();
        let num: i32 = match line.trim().parse() {
            Ok(num) => num,
            Err(_) => return Err(io::Error::new(io::ErrorKind::InvalidInput, "Invalid input"))};
        a[i] = num as usize};

    let mut count = 0;
    for i in 1..n-1 {
        if a[i-1] == 1 && a[i+1] == 1 && a[i] == 0 {
            a[i+1] = 0;
            count += 1;
        }
    }

    writeln!(io::stdout(), "{}", count)?;
    Ok(())
}
