    for (int i = 0; i < 475; i++) {
        if (eligible(x + diff, p, y)) {
            std::cout << "0";
            return 0;
        }
        diff -= 50;
    }
    diff = 0;
    for (int i = 0; i < 475; i++) {
        if (eligible(x + diff, p, y)) {
            int succ = diff / 100;
            int unsucc = (diff / 50) % 2; // if 1, we need additional success
            std::cout << succ + unsucc;
            return 0;
        }
        diff += 50;
    }
    return 0;
}
