    int n, k, x;
    std::cin >> n >> k >> x;

    std::vector<int> A(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> A[i];
    }

    std::vector<int> L(n + 1, 0);
    std::vector<int> R(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        L[i + 1] = A[i] | L[i];
    }
    for (int i = n - 1; i >= 0; --i) {
        R[i] = A[i] | R[i + 1];
    }

    x = x * k;

    int ans = 0;
    for (int i = 0; i < n; ++i) {
        ans = std::max(ans, L[i] | (A[i] * x) | R[i + 1]);
    }

    std::cout << ans << std::endl;

    return 0;
}
