import sys

class E:
    def __init__(self, id, deg, xor):
        self.id = id
        self.deg = deg
        self.xor = xor

    def __lt__(self, other):
        return self.deg < other.deg

def run():
    n = int(input())
    nodes = [E(i, int(input()), int(input())) for i in range(n)]
    nodes.sort()
    res = []
    q = []
    for node in nodes:
        if node.deg == 1:
            q.append(node.id)

    while q:
        id = q.pop()
        while nodes[id].deg == 1:
            adj = nodes[id].xor
            res.append([id, adj])
            nodes[id].deg -= 1
            nodes[adj].deg -= 1
            nodes[id].xor ^= adj
            nodes[adj].xor ^= id
            if nodes[adj].deg == 1:
                id = adj
            else:
                break

    print(len(res))
    for pair in res:
        print(pair[0], pair[1])

if __name__ == "__main__":
    run()
