import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        List<List<Integer>> listd = new ArrayList<>();
        int res = 0;

        for (int i = 0; i < n; i++) {
            listd.add(Arrays.asList(scan.nextInt(), scan.nextInt()));
        }

        listd.sort((a, b) -> {
            if (a.get(0) == b.get(0)) {
                return a.get(1) - b.get(1);
            } else {
                return a.get(0) - b.get(0);
            }
        });

        for (List<Integer> pair : listd) {
            res = Math.max(res, pair.get(0));
            res = Math.max(res, pair.get(1));
        }

        System.out.println(res);
    }
}
