import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        int k = scan.nextInt();
        PolandBall(n, k);
    }

    private static void PolandBall(int n, int k) {
        // Check for invalid input
        if (n < 4 || k > 3 || k == 1 || (k == 2 && n == 4)) {
            System.out.println("-1");
            return;
        }

        // Handle k = 2
        if (k == 2) {
            System.out.println(n - 1);
            for (int i = 1; i < n; i++) {
                System.out.println(i + " " + (i + 1));
            }
            return;
        }

