import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        List<String> lst = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String n = scan.next();
            lst.add(n.substring(4));
        }
        for (String i : lst) {
            int l = i.length();
            int iInt = Integer.parseInt(i);
            int g = 0;
            int p = 10;
            int c = 1;
            while (c < l) {
                g += p;
                p *= 10;
                c++;
            }
            while (iInt < 1989 + g) {
                iInt += p;
            }
            System.out.println(iInt);
        }
    }
}
