			fmt.Println(1)
		}
		return
	}

	np := make([]bool, 1300000)
	pn := 0
	for i := 2; i < np.length && i < x; i++ {
		if !np[i] {
			if binarySearch(a, i) < 0 {
				fmt.Println(-1)
				return
			}
			pn++
			for j := i * 2; j < np.length; j += i {
				np[j] = true
			}
		}
	}

	fmt.Println(pn)
}

func binarySearch(a []int, x int) int {
	l, r := 0, len(a)-1
	for l <= r {
		m := (l + r) / 2
		if a[m] == x {
			return m
		} else if a[m] < x {
			l = m + 1
		} else {
			r = m - 1
		}
	}
	return -1
}
