```c++
#include <iostream>
#include <string>
#include <vector>

int main() {
    int day = 4;
    std::string situations = "1 3 2 0";
    std::vector<int> dp(day + 1, std::vector<int>(3, 0));

    // Base Case:
    for (int j = 0; j < 3; ++j) {
        dp[0][j] = 0;
    }

    // Inductive Step:
    for (int i = 1; i <= day; ++i) {
        // 0: rest
        dp[i][0] = 1 + std::min(dp[i - 1][0], dp[i - 1][1], dp[i - 1][2]);
        // 1: gym
        dp[i][1] = std::min(dp[i - 1][0], dp[i - 1][2]);
        // 2. contest
        dp[i][2] = std::min(dp[i - 1][0], dp[i - 1][1]);

        if (situations[i - 1] == '0') {
            dp[i][1] = std::numeric_limits<int>::max();
            dp[i][2] = std::numeric_limits<int>::max();
        } else if (situations[i - 1] == '1') {
            dp[i][1] = std::numeric_limits<int>::max();
        } else if (situations[i - 1] == '2') {
            dp[i][2] = std::numeric_limits<int>::max();
        }
    }

    std::cout << std::min(dp[day][0], dp[day][1], dp[day][2]) << std::endl;

    return 0;
}
