#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a[i];
    }
    std::sort(a.begin(), a.end());
    int i = 0, ln = 1, nn = 1, j = n - 1;
    while (a[i] == a[i + 1] && i < n - 1 && a[0] != a[n - 1]) {
        ++i;
        ++nn;
    }
    while (a[j] == a[j - 1] && j > 0 && a[0] != a[n - 1]) {
        --j;
        ++ln;
    }
    int dis = a[n - 1] - a[0];
    if (a[0] != a[n - 1]) {
        k = ln * nn;
    } else {
        k = (n * (n - 1)) / 2;
    }
    std::cout << dis << " " << k << std::endl;
    return 0;
}
