        int n = scanner.nextInt();
        List<Integer> divisors = getDivisors(n);
        int count = 0;
        for (int d : divisors) {
            if (check(n, d)) {
                count++;
            }
        }
        System.out.println(count);
    }

    private static List<Integer> getDivisors(int n) {
        int m = (int) Math.sqrt(n) + 1;
        List<Integer> divisors = new ArrayList<>();
        for (int d = 1; d < m; d++) {
            if (n % d == 0) {
                divisors.add(d);
                divisors.add(n / d);
            }
        }
        return divisors;
    }

    private static boolean check(int n, int d) {
        String nStr = String.valueOf(n);
        String dStr = String.valueOf(d);
        for (char c : dStr.toCharArray()) {
            if (c >= '0' && c <= '9' && c >= nStr.charAt(0) && c <= nStr.charAt(nStr.length() - 1)) {
                return true;
            }
        }
        return false;
    }
}
