#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;
    std::vector<int> an(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> an[i];
    }

    std::vector<int> k(101, 0);
    for (int i = 0; i < n; ++i) {
        ++k[an[i]];
