namespace Codeforces {
    class Program {
        static void Main(string[] args) {
            int n = int.Parse(Console.ReadLine());
            int[] an = Array.ConvertAll(Console.ReadLine().Split(' '), x => int.Parse(x));

            int[] k = new int[101];
            for (int i = 0; i < n; i++) {
                k[an[i]]++;
            }

            int res = 0;
            for (int i = 0; i < 101; i++) {
                res += k[i] / 2;
            }

            Console.WriteLine(res / 2);
        }
    }
}
