        for (int i = 0; i < t; i++) {
            int n = scan.nextInt();
            int[] arr = new int[n];
            for (int j = 0; j < n; j++) {
                arr[j] = scan.nextInt();
            }
            int[] chance = new int[n + 1];
            chance[n - 1] = arr[n - 1];
            for (int j = n - 2; j >= 0; j--) {
                chance[j] = Math.max(chance[j + 1], arr[j + 1] - chance[j + 1] + chance[j]);
            }
            System.out.println(sum(arr) - chance[0] + " " + chance[0]);
        }
    }

    private static int sum(int[] arr) {
        int sum = 0;
        for (int i : arr) {
            sum += i;
        }
        return sum;
    }
}
