#include <iostream>
#include <cmath>

int C(int n, int k) {
    int w = 1;
    for (int i = n - k + 1; i <= n; i++) {
        w *= i;
    }
    for (int i = 1; i <= k; i++) {
        w /= i;
    }
    return w;
}

int multiples(int limit) {
    int tmp = 1;
    int m = limit;
    for (int j = 2; j <= limit; j++) {
        int no_multiples = 0;
        while (m % j == 0) {
            no_multiples += 1;
            m /= j;
        }
        if (no_multiples) {
            tmp *= C(no_multiples + k - 1, no_multiples);
        }
    }
    return tmp;
}

int main() {
    int n, k;
    std::cin >> n >> k;
    int modulo = 1000000007;
    int total = 0;
    for (int i = 1; i <= n; i++) {
        total += multiples(i);
    }
    std::cout << total % modulo << std::endl;
    return 0;
}
