package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

func quickSort(array []int, start int, end int) {
	if end-start > 0 {
		pivot := array[start]
		i := start
		k := end
		for k > i {
			for array[i] <= pivot && i <= end && k > i {
				i++
			}
			for array[k] > pivot && k >= start && k >= i {
				k--
			}
			if k > i {
				array[i], array[k] = array[k], array[i]
			}
		}
		array[start], array[k] = array[k], array[start]
		quickSort(array, start, k-1)
		quickSort(array, k+1, end)
	}
}

func main() {
	var total int
	_, err := fmt.Scanf("%d", &total)
	if err != nil {
		fmt.Println(err)
		return
