import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.BitSet;
import java.util.StringTokenizer;

public class e implements Runnable {

	public void solve(FS in, PrintWriter out) {
		int n = in.nextInt();
		int[] a = new int[n];
		for(int i = 0; i < n; ++i) a[i] = in.nextInt();
		int idx = 0;
		ArrayList<BitSet> ans = new ArrayList<>();
		for(int i = 0; i < n + 1; ++i) ans.add(new BitSet());
		for(int curVal = n; curVal >= 1; --curVal) {
			for(int i = 0; i < n; ++i) if(a[i] == curVal) {
				for(int times = 0; times < a[i]; ++times) {
					int cidx = (idx + times) % (n + 1);
					ans.get(cidx).set(i);
				}
				idx++;
			}
		}
		ArrayList<BitSet> nans = new ArrayList<>();
		for(BitSet cur : ans) if(cur.cardinality() > 0) nans.add(cur);
		out.println(nans.size());
		for(BitSet cur : nans) {
			for(int i = 0; i < n; ++i) out.print(cur.get(i) ? 1 : 0);
			out.println();
		}
	}

	public void run() {
		System.err.println("go!");
		FS in = new FS();
		PrintWriter out = new PrintWriter(System.out);
		solve(in, out);
		out.close();
	}

	public static void main(String[] args) {
		new Thread(null, new e(), "lmao", 1L<<28).start();
