#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

int main() {
    int n, k;
    std::cin >> n >> k;

    std::vector<int> coins(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> coins[i];
    }

    int coinsUsed = 0;
    while (coins[k - 1] > 0) {
        int count = coins[k - 1];
        for (int i = 1; i < k; ++i) {
            if (count > coins[i]) {
                count -= coins[i];
                coins[i] += coins[i + 1];
            } else {
                break;
            }
        }
        coinsUsed++;
    }

    std::cout << coinsUsed << std::endl;

    return 0;
}
