            List<List<int>> graph = new List<List<int>>();
            for (int i = 0; i < n; i++) {
                int m = int.Parse(Console.ReadLine());
                graph.Add(new List<int>());
                for (int j = 0; j < m; j++) {
                    int temp = int.Parse(Console.ReadLine());
                    if (temp > 0) {
                        graph[i].Add(temp);
                    }
                }
            }
            List<List<int>> components = new List<List<int>>();
            bool[] visited = new bool[n];
            Stack<int> stack = new Stack<int>();
            int time = 0;
            int[] lowlink = new int[n];
            for (int u = 0; u < n; u++) {
                if (!visited[u]) {
                    dfs(u);
                }
            }
            for (int u = 0; u < n; u++) {
                if (lowlink[u] == time) {
                    List<int> component = new List<int>();
                    while (true) {
                        int x = stack.Pop();
                        component.Add(x);
                        lowlink[x] = int.MaxValue;
                        if (x == u) {
                            break;
                        }
                    }
                    components.Add(component);
                }
            }
            Console.WriteLine(components.Count == 1 ? "YES" : "NO");
        }

        static void dfs(int u) {
            lowlink[u] = time++;
            visited[u] = true;
            stack.Push(u);
            bool isComponentRoot = true;

            foreach (int v in graph[u]) {
                int v2 = v - 1;
                if (!visited[v2]) {
                    dfs(v2);
                }
                if (lowlink[u] > lowlink[v2]) {
                    lowlink[u] = lowlink[v2];
                    isComponentRoot = false;
                }
            }

            if (isComponentRoot) {
                List<int> component = new List<int>();
                while (true) {
                    int x = stack.Pop();
                    component.Add(x);
                    lowlink[x] = int.MaxValue;
                    if (x == u) {
                        break;
                    }
                }
                components.Add(component);
            }
        }
    }
