#include <iostream>
#include <vector>
#include <unordered_map>
#include <algorithm>

int main() {
    int n, m;
    std::cin >> n >> m;

    std::vector<int> r(n);
    std::unordered_map<int, std::vector<int>> p;

    int i = 0;
    while (i < n - m) {
        int t, x;
        std::cin >> t >> x;
        p[x].push_back(i);
        i += m;
    }

    int d = 0;
    for (int i = 0; i < n; ++i) {
        if (p.find(i) != p.end()) {
            r[i] = d + p[i][0];
            d = std::max(t, d) + (p[i].size() + 1) / 2;
        } else {
            r[i] = d;
            d += 2;
        }
    }

    for (int i = 0; i < n; ++i) {
        std::cin >> t >> x;
        p[x].push_back(i);
    }

    if (!p.empty()) {
        d = std::max(t, d);
        for (auto& pair : p) {
            r[pair.first] = d + pair.first;
            d += (pair.second.size() + 1) / 2;
        }
    }

    for (int i = 0; i < n; ++i) {
        std::cout << r[i] << " ";
    }

    return 0;
}
