import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        String[] a_list = br.readLine().split(" ");
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(a_list[i]);
        }

        String out = "";
        int cur = 1000;
        int pref_size = 0;
        int cur_max = 1000;
        int cur_min = 1000;
        for (int k = 0; k < n; k++) {
            for (int i = 0; i < arr[k]; i++) {
                int ind = pref_size + i;
                if (k % 2 == 0) {
                    out = out.substring(0, ind) + "/" + out.substring(ind + 1);
                    cur++;
                } else {
                    out = out.substring(0, ind) + "\\" + out.substring(ind + 1);
                    cur--;
                }
            }

            if (k % 2 == 1) {
                cur++;
                cur_min = Math.min(cur_min, cur);
            } else {
                cur--;
                cur_max = Math.max(cur_max, cur);
            }

            pref_size += arr[k];
        }

        for (int i = cur_max; i >= cur_min - 1; i--) {
            System.out.println(out);
        }
    }
}
