#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

int main() {
    int n;
    std::cin >> n;

    std::vector<std::vector<int>> arr(n, std::vector<int>(n));
    std::vector<std::vector<int>> visited(n, std::vector<int>(n));

    for (int i = 0; i < n; i++) {
        std::string a;
        std::cin >> a;
        std::istringstream iss(a);
        std::string token;
        while (iss >> token) {
            arr[i][std::stoi(token)] = 1;
        }
    }

    if (n == 1) {
        std::cout << arr[0][0] << std::endl;
        return 0;
    }

    int middleR = (n - 1) / 2;
    int middleC = (n - 1) / 2;
    int total = 0;

    for (int i = 0; i < n; i++) {
        if (visited[middleR][i] == 0) {
            visited[middleR][i] = 1;
            total += arr[middleR][i];
        }
    }

    for (int i = 0; i < n; i++) {
        if (visited[i][middleC] == 0) {
            visited[i][middleC] = 1;
            total += arr[i][middleC];
        }
    }

    for (int i = 0; i < n; i++) {
        if (visited[i][i] == 0) {
            visited[i][i] = 1;
            total += arr[i][i];
        }
    }

    int ku = 0;
    for (int i = 0; i < n; i++) {
        int kkt = n - 1 - i;
        if (visited[ku][kkt] == 0) {
            visited[ku][kkt] = 1;
            total += arr[ku][kkt];
        }
        ku++;
    }

    std::cout << total << std::endl;

    return 0;
}
