#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n, k1, k2;
    std::cin >> n >> k1 >> k2;
    std::vector<int> a1(n), a2(n);
    for (int i = 0; i < n; ++i) {
        std::cin >> a1[i];
    }
    for (int i = 0; i < n; ++i) {
        std::cin >> a2[i];
    }

    std::vector<int> e(n);
    for (int i = 0; i < n; ++i) {
        e[i] = std::abs(a1[i] - a2[i]);
    }

    for (int k = 0; k < k1 + k2; ++k) {
        e[e.begin() + std::distance(e.begin(), std::max_element(e.begin(), e.end()))] = std::abs(std::max_element(e.begin(), e.end()) - 1);
    }

    int sum = 0;
    for (int i : e) {
        sum += i * i;
    }

    std::cout << sum << std::endl;

    return 0;
}
