  for (int i = 0; i < s.length(); i++) {
    cnt[s[i] - 'a']++;
  }
  int index = 0;
  for (int i = 0; i < s.length(); i++) {
    cnt[s[i] - 'a']--;
    while (index < 26 && cnt[index] == 0) {
