import java.util.*;
import java.lang.Math;

public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int bx = scan.nextInt();
        int by = scan.nextInt();
        int n = scan.nextInt();
        int ans = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int x = scan.nextInt();
            int y = scan.nextInt();
            int v = scan.nextInt();
            double dist = Math.sqrt((x - bx) * (x - bx) + (y - by) * (y - by)) / v;
            ans = Math.min(ans, dist);
        }
        System.out.println(ans);
    }
}
