    dist = lambda f1, f2, v: math.sqrt(f1*f1+f2*f2) / v
    n = int(input())
    ans = sys.maxsize
    for _ in range(n):
        x,y,v = map(int, input().split())
        ans = min(ans, dist(x-bx, y-by,v))
    return ans

