    cin >> n;
    vector<int> parent(n + 1);
    for (int i = 1; i <= n; ++i) {
        parent[i] = i - 1;
    }
    vector<int> citizen(n);
    for (int i = 0; i < n; ++i) {
        cin >> citizen[i];
    }
    vector<int> sz(n + 1, 0);
    for (int i = 1; i <= n; ++i) {
        sz[parent[i]] = 0;
    }
    for (int i = n - 1; i >= 1; --i) {
        sz[parent[i]] += sz[i];
        citizen[parent[i]] += citizen[i];
    }
    int ans = 0;
    for (int i = 1; i <= n; ++i) {
        if (sz[i] == 0 || (citizen[i] % sz[i]) == 0) {
            ans = max(ans, citizen[i] / sz[i]);
        } else {
            ans = max(ans, (citizen[i] / sz[i]) + 1);
        }
    }
    cout << ans << endl;
    return 0;
}
