import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String input = scanner.nextLine();
        int[] count = new int[input.length() + 1];
        String s = input;
        for (int i = 0; i < input.length(); i++) {
            if (input.charAt(i) == 'V') {
                if (i != input.length() - 1) {
                    s = s.substring(0, i) + "K" + s.substring(i + 1);
                } else {
                    s = s.substring(0, i) + "K";
                }
            } else {
                if (i != input.length() - 1) {
                    s = s.substring(0, i) + "V" + s.substring(i + 1);
                } else {
                    s = s.substring(0, i) + "V";
                }
            }
            count[i + 1] = s.split("VK").length - 1;
            s = input;
        }
        System.out.println(Math.max(count));
    }
}
