				s = s[:i] + "V" + s[i+1:]
			} else {
				s = s[:i] + "V"
			}
		}
		count[i+1] = strings.Count(s, "VK")
		s = input
	}
	sort.Ints(count)
	fmt.Println(count[len(input)-1])
}
