                return;
            }
        };
        a.push(num);
    }

    a.sort();

    let mut visited: Vec<bool> = Vec::new();
    visited.push(false);
    let mut b: Vec<pair> = Vec::new();
    for _ in 0..n {
        b.push(pair{ele: 0, index: 0});
    }

    let mut k = 0;
    for _ in 1..n {
        if a[_] == a[_ - 1] {
            b[k].ele = a[_];
            b[k].index = _;
            k += 1;
        }
    }

    let mut c: Vec<usize> = Vec::new();
    let mut h = 0;
    for _ in 1..=n {
        if visited[_] == false {
            c.push(_);
            h += 1;
        }
    }
    for _ in n + 1..=6000 {
        c.push(_);
        h += 1;
    }

    let mut j = 0;
    let mut count = 0;
    for _ in 0..k {
        while b[_].ele >= c[j] {
            j += 1;
        }
        count += c[j] - b[_].ele;
        j += 1;
    }

