import java.math.*;
public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        int ans = 0;
        if (n < 3) {
            ans = n;
        } else if (n % 2 != 0) {
            ans = n * (n - 1) * (n - 2);
        } else {
            int a = 0;
            if (gcd(n, n - 3) == 1) {
                a = n * (n - 1) * (n - 3);
            }
            n -= 1;
            ans = Math.max(n * (n - 1) * (n - 2), a);
        }
        System.out.println(ans);
    }
}
