    def __init__(self, s=None):
        self.in = io.StringIO(s) if s else sys.stdin
        self.bId = 0
        self.size = 0
        self.c = None
        self.num = 1
        self.BS = 1 << 16
        self.NC = None

    def nextChar(self):
        while self.bId == self.size:
            try:
                self.size = self.in.read(self.BS)
            except Exception:
                return None
            if self.size == -1:
                return None
            self.bId = 0
        return self.c

    def nextInt(self):
        return int(self.nextLong())

    def nextLong(self):
        self.c = None
        self.num = 1
        if self.c is None:
            self.c = self.nextChar()
        if self.c is None:
            return None
        if self.c == '-':
            self.num = -1
            self.c = self.nextChar()
        for c in self.c:
            if c < '0' or c > '9':
                self.c = self.nextChar()
                break
            self.num = (self.num << 3) + (self.num << 1) + (ord(c) - ord('0'))
        return self.num * self.num

    def nextDouble(self):
        return self.nextLong() + self.nextLong() / self.num

    def next(self):
        res = ''
        while self.c <= 32:
            self.c = self.nextChar()
        while self.c > 32:
            res += self.c
            self.c = self.nextChar()
        return res

    def nextLine(self):
        res = ''
        while self.c <= 32:
            self.c = self.nextChar()
        while self.c != '\n':
            res += self.c
            self.c = self.nextChar()
        return res

    def hasNext(self):
        if self.c > 32:
            return True
        while True:
            self.c = self.nextChar()
            if self.c is None:
                return False
            if self.c > 32:
                return True
        return False

    def nextIntArray(self, n):
        res = []
        for i in range(n):
            res.append(self.nextInt())
        return res

