#include <iostream>
#include <string>
#include <vector>

int main() {
    std::string input;
    std::cin >> input;

    std::istringstream iss(input);
    std::vector<std::string> tokens;
    std::string token;
    while (iss >> token) {
        tokens.push_back(token);
    }

    int n = stoi(tokens[0]);
    int x = stoi(tokens[1]);
    int y = stoi(tokens[2]);

    int a = y - n + 1;
    if (a <= 0) {
        std::cout << -1 << std::endl;
    } else {
        if (a * a + n - 1 >= x) {
            std::cout << a << std::endl;
            for (int i = 0; i < n - 1; ++i) {
                std::cout << 1 << std::endl;
            }
        } else {
            std::cout << -1 << std::endl;
        }
    }

    return 0;
}
