use std::io::{self, Write};
use std::cmp::{max, min};
use std::collections::HashMap;

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines: Vec<String> = input.split('\n').map(|x| x.to_string()).collect();
    let mut n: usize = lines[0].parse().unwrap();
    let mut k: usize = lines[1].parse().unwrap();
    let mut st: String = lines[2].clone();
    let mut arr: HashMap<char, usize> = HashMap::new();
    for i in 0..n {
        let ch: char = st.chars().nth(i).unwrap();
        *arr.entry(ch).or_insert(0) += 1;
    }
    let mut ans: usize = 0;
    for (ch, cnt) in arr {
        ans = max(ans, cnt * k);
    }
    println!("{}", ans);
}
