func main() {
	var n int
	_, err := fmt.Scanf("%d", &n)
	if err != nil {
		fmt.Println(err)
		return
	}

	a := make([]int, 2*n)
	for i := 0; i < 2*n; i++ {
		_, err := fmt.Scanf("%d", &a[i])
		if err != nil {
			fmt.Println(err)
			return
		}
	}

	sort.Ints(a)

	minArea := a[0] - a[n-1]
	deltaY := a[2*n-1] - a[0]
	for i := 1; i < n; i++ {
		x1 := a[i]
		x2 := a[i+n-1]
		minArea = min(minArea, abs(x1-x2)*deltaY)
	}

	fmt.Println(minArea)
}

func min(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func abs(a int) int {
	if a < 0 {
		return -a
	}
	return a
}
