public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int t = scan.nextInt();
        for (int i = 0; i < t; i++) {
            int n = scan.nextInt();
            String[] arr = scan.next().split(" ");
            int[] nums = new int[n];
            for (int j = 0; j < n; j++) {
                nums[j] = Integer.parseInt(arr[j]);
            }
            int result = findSubArray(nums, n);
            if (result == 1) {
                System.out.println("YES");
                System.out.println((result - 1) + " " + result);
            } else {
                System.out.println("NO");
            }
        }
    }

    private static int findSubArray(int[] nums, int n) {
        for (int i = 0; i < n - 1; i++) {
            if (Math.abs(nums[i] - nums[i + 1]) > 1) {
                return i + 1;
            }
        }
        return 0;
    }
}
