use std::io::{self, Write};
use std::num::ParseIntError;

fn main() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let n: usize = input.trim().parse::<usize>()?;
    let mut xarray = vec![0; 101];
    let mut yarray = vec![0; 101];
    let mut xmax = -1;
    let mut ymax = -1;

    for _ in 0..n {
        let [x, y] = input.trim().split(' ').map(|s| s.parse::<usize>().unwrap());
        xarray[x] = 1;
        yarray[y] = 1;
        xmax = std::cmp::max(x, xmax);
        ymax = std::cmp::max(y, ymax);
    }

    let mut xall = 0;
    for i in 0..=xmax {
        xall += xarray[i];
    }

    let mut yall = 0;
    for i in 0..=ymax {
        yall += yarray[i];
    }

    println!("{}", std::cmp::min(xall, yall));
    Ok(())
}
