import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE_cf92 solver = new TaskE_cf92();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE_cf92 {
        long res = 0;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            Graph g = new Graph();
            g.initGraph(n, n - 1);
            for (int i = 0; i < n - 1; ++i) {
                g.addEdge(in.nextInt() - 1, in.nextInt() - 1);
            }
            int[] a = new int[n];
            int[] b = new int[n];
            int sa = 0, sb = 0;
            for (int i = 0; i < n; ++i) {
                a[i] = in.nextInt();
                b[i] = in.nextInt();
                sa += a[i];
                sb += b[i];
            }
            int[] am = new int[n];
            dfs(0, -1, g, a, b, am, sa);
            out.println((double) res / (double) (sa * 1L * sb));
        }

        void dfs(int v, int p, Graph g, int[] a, int[] b, int[] am, int sa) {
            am[v] = 1;
            for (int ei = g.first[v]; ei != -1; ei = g.next[ei]) {
                int to = g.to[ei];
                if (to == p) continue;
                dfs(to, v, g, a, b, am, sa);
                am[v] += am[to];
                a[v] += a[to];
                if (b[v] != 0) {
                    res += b[v] * 1L * am[to] * 1L * a[to];
                }
            }
            if (b[v] != 0) {
                res += b[v] * 1L * (sa - a[v]) * 1L * (g.nVertex - am[v]);
            }
        }

    }

