using System;
using System.IO;
using System.Threading;

namespace A {
    class Program {
        static void Main(string[] args) {
            var sc = new Scanner(new BufferedReader(new InputStreamReader(
                Console.In)));
            while (sc.hasNextInt()) {
                int n = sc.nextInt();
                int k = sc.nextInt();
                int px = sc.nextInt();
                int py = sc.nextInt();
                double total = 0;
                for (int i = 1; i < n; i++) {
                    int nx = sc.nextInt();
                    int ny = sc.nextInt();
                    int dx = px - nx;
                    int dy = py - ny;
                    total += Math.Sqrt(dx * dx + dy * dy);
                    px = nx;
                    py = ny;
                }
                Console.WriteLine(k * (total / 50));
            }
        }
    }

    public class Scanner : IDisposable {
        private readonly TextReader reader;
        private readonly char[] buffer;

        public Scanner(TextReader reader) {
            this.reader = reader;
            this.buffer = new char[1024];
        }

        public bool hasNextInt() {
            return reader.Read(buffer, 0, buffer.Length) > 0;
        }

        public int NextInt() {
            var index = 0;
            while (index < buffer.Length && char.IsWhiteSpace(buffer[index])) {
                index++;
            }
            var result = int.Parse(new string(buffer, index, buffer.Length - index));
            index += result.ToString().Length;
            while (index < buffer.Length && char.IsWhiteSpace(buffer[index])) {
                index++;
            }
            return result;
        }

        public void Dispose() {
            reader.Dispose();
        }
    }
}
