import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int b = scan.nextInt();
        List<Integer> out = new ArrayList<>();
        out.add(1);
        int n = b;
        int i = 0;
        while (n % 2 == 0) {
            i++;
            out.add((int) Math.pow(2, i));
            n = n / 2;
        }
        List<Integer> out1 = new ArrayList<>();
        for (int i1 = 1; i1 < (int) Math.sqrt(n) + 1; i1 += 2) {
            if (n % i1 == 0) {
                out1.add(i1);
                out1.add(n / i1);
            }
        }
        Set<Integer> out2 = new HashSet<>();
        for (int i2 : out) {
            for (int i3 : out1) {
                out2.add(i2 * i3);
            }
        }
        System.out.println(out2.size());
    }
}
