            flag = 1;
        } else if (gr > bl && gr - 1 == bl) {
            flag = 1;
        } else if (bl > gr && 2 * gr + 2 >= bl) {
            flag = 1;
        }
    }
    if (flag == 0) {
        cout << "NO" << endl;
    } else {
        cout << "YES" << endl;
    }
    return 0;
}
