        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int testCount = Integer.parseInt(br.readLine());
        for (int i = 1; i <= testCount; i++) {
            int n = Integer.parseInt(br.readLine());
            long[] arr = new long[n];
            for (int j = 0; j < n; j++) {
                arr[j] = Long.parseLong(br.readLine());
            }

            if (n == 1) {
                System.out.println(1);
                continue;
            }

            Arrays.sort(arr);

            long minVal = Math.abs(arr[0]);
            int firstPositiveIndex = -1;
            long firstPositive = -1;

            for (int j = 0; j < n; j++) {
                if (arr[j] > 0) {
                    firstPositive = arr[j];
                    firstPositiveIndex = j;
                    break;
                }
            }

            if (firstPositive == -1) {
                System.out.println(n);
                continue;
            }

            for (int j = 1; j <= firstPositiveIndex; j++) {
                if (Math.abs(arr[j] - arr[j - 1]) < minVal) {
                    System.out.println(firstPositiveIndex);
                    break;
                }
            }

            System.out.println(firstPositiveIndex + 1);
        }
    }
}
