r = int(input())
if r % 2 == 0:
    print("NO")
    exit()
if r < 4:
    print("NO")
    exit()
r -= 1
r //= 2
print("1", r - 1)
``````javascript
const input = require('readline').createInterface({
  input: process.stdin,
  output: process.stdout
});

input.on('line', (r) => {
  if (r % 2 == 0) {
    console.log("NO");
    process.exit();
  }
  if (r < 4) {
    console.log("NO");
    process.exit();
  }
  r--;
  r /= 2;
  console.log("1 " + (r - 1));
});
``````csharp
using System;
using System.IO;
class Program {
    static void Main(string[] args) {
        using (var reader = new StreamReader(Console.OpenStandardInput())) {
            var r = long.Parse(reader.ReadLine());
            if (r % 2 == 0) {
                Console.WriteLine("NO");
                return;
            }
            if (r < 4) {
                Console.WriteLine("NO");
                return;
            }
            r--;
            r /= 2;
            Console.WriteLine("1 " + (r - 1));
        }
    }
}
