import java.util.*;
public class Main {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        int[] s = new int[n];
        for (int i = 0; i < n; i++) {
            s[i] = scan.nextInt();
        }
        int el = Arrays.stream(s).max().getAsInt();
        int pos1 = -1, pos2 = -1, c = 0, ans = 0;
        for (int i : s) {
            if (i == el) {
                c++;
            } else {
                ans = Math.max(ans, c);
                c = 0;
            }
        }
        ans = Math.max(ans, c);
        System.out.println(ans);
    }
}
