import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int m = n;
        int mx = (n * (n - 1)) >> 1;
        int result = -1;
        for (int i = m; i <= mx; i++) {
            if (isPrime(i)) {
                result = i;
                break;
            }
        }
        System.out.println(result);

        List<List<Integer>> combinations = generateCombinations(n, n - 2);
        for (List<Integer> combination : combinations) {
            int sum = combination.stream().mapToInt(i -> i).sum();
            if (sum == n) {
                System.out.println(combination.stream().map(i -> i + 1).collect(Collectors.joining(" ")));
            }
        }
    }

    // Function to check if a number is prime
    private static boolean isPrime(int n) {
        if (n <= 1) return false;
        for (int i = 2; i < n; i++) {
            if (n % i === 0) return false;
        }
        return true;
    }

    // Function to generate all possible combinations of numbers
    private static List<List<Integer>> generateCombinations(int n, int k) {
        List<List<Integer>> combinations = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            List<Integer> combination = new ArrayList<>();
            for (int j = 0; j < k; j++) {
                combination.add(i + 1);
            }
            combinations.add(combination);
        }
        return combinations;
    }
}
