// Function to check if a number is prime
function isPrime(n) {
  if (n <= 1) return false;
  for (let i = 2; i < n; i++) {
    if (n % i === 0) return false;
  }
  return true;
}

// Function to generate all possible combinations of numbers
function generateCombinations(n, k) {
  const combinations = [];
  for (let i = 0; i < n; i++) {
    const combination = [];
    for (let j = 0; j < k; j++) {
      combination.push(i + 1);
    }
    combinations.push(combination);
  }
  return combinations;
}

// Main function to solve the problem
function solve() {
  const n = parseInt(input());
  const m = n;
  const mx = (n * (n - 1)) >> 1;
  let result = -1;
  for (let i = m; i <= mx; i++) {
    if (isPrime(i)) {
      result = i;
      break;
    }
  }
  console.log(result);

  const combinations = generateCombinations(n, n - 2);
  for (const combination of combinations) {
    const sum = combination.reduce((a, b) => a + b, 0);
    if (sum === n) {
      console.log(combination.join(' '));
    }
  }
}

