            System.out.println("undefined");
        } else {
            if (t == 1) {
                if ((b - 1) % 4 == a) {
                    System.out.println("CW".toLowerCase());
                } else {
                    System.out.println("CCW".toLowerCase());
                }
            } else if (t == 3) {
                if ((b + 1) % 4 == a) {
                    System.out.println("CW".toLowerCase());
                } else {
                    System.out.println("CCW".toLowerCase());
                }
            }
        }
    }
